D.SpellTexts[62425]={Description={["9c238a0c7956d9ff:234"]="将发动机的所有动力供给武器系统。\r\n\r\n   200-500动力：\r\n        伤害提高20%。\r\n        持续20秒。\r\n\r\n   500-800动力：\r\n        伤害提高30%。\r\n        持续30秒。\r\n\r\n   800-1100动力：\r\n        伤害提高40%。\r\n        持续40秒。\r\n\r\n   1100以上动力：\r\n        伤害提高50%。\r\n        持续50秒。"}}
D.SpellTexts[62426]={Description={["c40d9f1ba00ee846:234"]="将发动机的所有动力供给传动系统，提高速度。\r\n\r\n   200-500动力：\r\n        20%移动速度。\r\n        持续20秒。\r\n\r\n   500-800动力：\r\n        30%移动速度。\r\n        持续30秒。\r\n\r\n   800-1100动力：\r\n        40%移动速度。\r\n        持续40秒。\r\n\r\n   1100以上动力：\r\n        50%移动速度。\r\n        持续50秒。"}}
