D.SpellTexts[66865]={Description={["12b5b3feea75fce1:75"]="耶德瑞克的近战攻击有一定的几率使他的下一次近战攻击造成爆击。"},Aura={["3b181e55bc4bdb08:75"]="近战攻击有一定几率使施法者的下一次近战攻击造成爆击。"}}
D.SpellTexts[66869]={Description={["3c28ffcaebe822cb:144"]="使敌人浑身溅满灼热的胆汁，对其及其周围的盟友造成持续性的火焰伤害。冰虫的灼热胆汁对于清除麻痹毒素非常有效。"}}
D.SpellTexts[66893]={Description={["cbdb3695b921e1e2:44"]="随意射出榴弹，让它们像婚礼上的老鼠一样乱窜。"}}
