D.SpellTexts[67435]={Aura={["05c60cfbd9d1d190:137"]="你的样子像极了贸易大王加里维克斯的巨怪保安。从他们身边溜过去，去“取得”你需要的东西。但一定要小心肚肥鼻尖的猪！！！"}}
