D.SpellTexts[67518]={Rank={["1044fc4816ed2acb:5"]="等级 7"}}
D.SpellTexts[67522]={Description={["8c947d45b88f6a38:127"]="将卡亚矿钻从你的地精百宝腰带上取下来，钻穿保险库大门的封锁装置。卡亚矿：绝无代用品！"}}
D.SpellTexts[67523]={Description={["df97995bc432ef6c:29"]="使敌人燃烧……致死！"}}
D.SpellTexts[67524]={Description={["8501aa0848c45161:128"]="把地精百宝腰带中的顺风耳人造耳朵扩展到库门上以听到弹簧锁的声响。内含全真巨魔耳朵！"}}
D.SpellTexts[67525]={Description={["4886f6984e92d017:162"]="尝试用你的地精百宝腰带上的无限复杂开锁器撬开这座保险库的门。当然，那根腰带上的撬锁工具太多了，你也许需要一些时间才能把它找出来。"}}
D.SpellTexts[67526]={Description={["0974c666b8585b1d:124"]="极具破坏性和危险性的神奇地精射线设备就安装在你的地精百宝腰带上，用它炸开锁住的保险库大门。"}}
D.SpellTexts[67527]={Description={["1e975af7e185bf5c:44"]="右键点击以召唤或解散墨玉猎豹。"}}
D.SpellTexts[67534]={Description={["93243f31c8c9134c:74"]="在目标身上施加一个妖术，目标受到的所有直接治疗效果也会被施加到周围的敌人身上。"},Aura={["6e77c7f4883ba1eb:44"]="获得的直接治疗效果也会被施加到周围的敌人身上。"}}
