D.SpellTexts[67554]={Description={["f26e93df66bb6f72:44"]="让周围的一个目标沐浴在纷飞的玫瑰花雨中！"},Aura={["3e4d27987483c9e1:41"]="你被小艾德琳撒下的花雨笼罩了！"}}
