D.SpellTexts[72174]={Description={["7e96a70a2d69b4c3:47"]="你变成翼手龙幻影。"},Aura={["ac56871c97249ba7:78"]="你变成翼手龙幻影。只在尖啸河滩有效。"}}
D.SpellTexts[72176]={Description={["28da47ce25685359:71"]=S[19483]},Aura={["28da47ce25685359:71"]=S[19483]}}
D.SpellTexts[72178]={Description={["b7a03f70fb2cab09:77"]=S[18614]},Aura={["db2d2e1a8c234785:68"]="技能和召唤生物所造成的伤害可生成鲜血能量。"}}
D.SpellTexts[72181]={Description={["7fb36829593c0160:44"]="你变成猩猩幻影。"},Aura={["5f86a0f2c86f6ebb:66"]="你变成猩猩幻影。只在蘑菇石有效。"}}
D.SpellTexts[72183]={Description={["1026c183e4cf85dc:35"]="测试一头安戈洛猩猩的知识。"},Aura={["8b437c5ff5cb614a:45"]="你已经测试了这头安戈洛猩猩的知识。"}}
D.SpellTexts[72184]={Description={["9d6ae9e33c60b640:35"]="测试一头安戈洛巨猩猩的知识。"},Aura={["1887a4bf4d5c91ae:45"]="你已经测试了安戈洛巨猩猩的知识。"}}
D.SpellTexts[72185]={Description={["ec8a7f0a51136b6d:37"]="测试一头安戈洛大猩猩的知识。"},Aura={["a1c160e6a1fc6fdb:47"]="你已经测试了安戈洛大猩猩的知识。"}}
D.SpellTexts[72188]={Aura={["ae6a0b3273ca3419:30"]="被双帆龙幻影咬了。"}}
D.SpellTexts[72189]={Description={["85efc70b5efb8bea:48"]="你变成双帆龙幻影。"},Aura={["458f3ec4cc89e3d1:74"]="你变成双帆龙幻影。只在马绍尔哨站有效"}}
D.SpellTexts[72190]={Aura={["85d6635172dd714a:47"]="作为双帆龙幻影所遭受的人形怪物撕咬次数。"}}
D.SpellTexts[72194]={Description={["b7c9250676e95a2b:92"]="使用盾牌猛击敌人，对其造成物理伤害并打断目标正在施放的法术。"}}
D.SpellTexts[72195]={Description={["b7a03f70fb2cab09:77"]=S[18614]}}
D.SpellTexts[72207]={Description={["b35172c0d1f0bb37:18"]="火炮冲击开火。"}}
D.SpellTexts[72231]={Description={["54f01b651eb0b5fc:10"]="连结光环。"},Aura={["54f01b651eb0b5fc:10"]="连结光环。"}}
D.SpellTexts[72232]={Aura={["23cdd910314409bb:33"]="不会受到守护之魂的影响。"}}
D.SpellTexts[72240]={Aura={["5839fc2fb2c2d3d4:74"]="使用B.C.消除者的火炮守卫胶囊镇不受乌姆洛特战士的侵扰。"}}
D.SpellTexts[72244]={Description={["36ef878f7444df0e:43"]="将目标传送到附近山崖的顶部。"}}
D.SpellTexts[72246]={Description={["36ac1dd42fc833ab:48"]="对被遗忘者入侵军队抛掷毁灭性的铁制炸弹。"}}
D.SpellTexts[72256]={Description={["d8322c0a85c799a5:112"]="死亡使者萨鲁法尔的近战攻击会对被标记为阵亡勇士的目标造成伤害，对它们造成额外的物理伤害。"}}
D.SpellTexts[72262]={Description={["5fa1c427dc7fcde2:67"]="发动强大的震荡波，使平台的边缘开始破碎。"}}
D.SpellTexts[72268]={Aura={["979997f4ce4e183b:8"]=S[13681]}}
D.SpellTexts[72286]={Description={["e315d5ff4b89841a:104"]="召唤或解散一匹可飞翔的骸骨战马－－无敌。这种坐骑的速度会根据你的骑术等级和所在区域改变。"}}
D.SpellTexts[72290]={Description={["f00e601d1e07a774:68"]=S[10700]},Aura={["f00e601d1e07a774:68"]=S[10700]}}
D.SpellTexts[72294]={Description={["d7de348bf1d41202:37"]="吞噬死去旅行者的遗体。"}}
D.SpellTexts[72321]={Aura={["660b8706d9fe846f:15"]=S[6322]}}
D.SpellTexts[72335]={Aura={["979997f4ce4e183b:8"]=S[13681]}}
D.SpellTexts[72339]={Description={["0f15fa2387c0b43c:77"]="从大炮中射出一个救生火箭背包，让它们飞向热砂港幸存者！"}}
D.SpellTexts[72343]={Aura={["785be2184a7b4481:10"]=S[21317]}}
D.SpellTexts[72351]={Aura={["b051e555b3c4de30:16"]="不能复活。"}}
D.SpellTexts[72362]={Description={["6f7df29867b9815f:64"]="腐蚀圆环中的目标，提高其受到的暗影伤害。"}}
D.SpellTexts[72374]={Aura={["d76e5fcde3c186f2:136"]=S[2269]}}
D.SpellTexts[72377]={Aura={["edc487939ad016a4:45"]="你正在通过观察平台指明目标。"}}
D.SpellTexts[72388]={Aura={["f05e6dde8757248d:65"]="正站在要塞的观察平台上。为射手指明目标！"}}
D.SpellTexts[72401]={Description={["aab95c5bc95d5436:12"]="镜像之名"},Aura={["aab95c5bc95d5436:12"]="镜像之名"}}
D.SpellTexts[72408]={Description={["015a065fc23fab1e:78"]="当萨鲁法尔对标记有血之符文的目标发动近战攻击时，他会从中吸取生命值。"}}
D.SpellTexts[72410]={Description={["48f753ea3125b105:89"]="萨鲁法尔的近战攻击会从目标身上吸取生命值，而所吸取的生命值将会成倍治疗他。"}}
D.SpellTexts[72423]={Description={["73771f2bae426186:32"]="复活所有附近阵亡的友方。"}}
D.SpellTexts[72424]={Description={["5d70c2f85fdd5831:37"]=S[6132]},Aura={["fe96f7c719cd79c6:22"]="体内充满了生命的能量。"}}
D.SpellTexts[72428]={Aura={["979997f4ce4e183b:8"]=S[13681]}}
D.SpellTexts[72437]={Description={["7577d8a2a0540c4b:47"]="你现在是毒肿的目标！"},Aura={["7577d8a2a0540c4b:47"]="你现在是毒肿的目标！"}}
D.SpellTexts[72454]={Description={["c4727c1431f5873b:21"]=S[20522]},Aura={["c4727c1431f5873b:21"]=S[20522]}}
D.SpellTexts[72466]={Description={["5d70c2f85fdd5831:37"]=S[6132]},Aura={["dd1b9631dabe5c92:39"]="生命的能量在庇护着辛达苟萨的灵魂。"}}
D.SpellTexts[72518]={Description={["afbbda2dcbd3515c:46"]="让目标陷入一股无法逃脱的旋风中。"},Aura={["47c4557e20bdd3e3:9"]="被困住！"}}
D.SpellTexts[72520]={Description={["15abb9236cc4a662:29"]="掷向一幢建筑，将其点燃。"}}
D.SpellTexts[72522]={Aura={["47c4557e20bdd3e3:9"]="无法行动！"}}
D.SpellTexts[72546]={Aura={["ca55a7c33997cd62:37"]="你的灵魂被霜之哀伤吞噬了。"}}
D.SpellTexts[72547]={Description={["1ec9152cc906e021:22"]="召唤梅格斯·碎纸机。"}}
D.SpellTexts[72580]={Description={["afbbda2dcbd3515c:46"]="让目标陷入一股无法逃脱的旋风中。"},Aura={["47c4557e20bdd3e3:9"]="被困住！"}}
D.SpellTexts[72585]={Description={["fd4751a1376d4f6e:23"]="从虚空中迸射出的灵魂。"}}
D.SpellTexts[72586]={Rank={["1044fc4216ed2ac5:5"]="等级1"}}
D.SpellTexts[72589]={Description={["16be060ba170889a:33"]="将邪恶之力导入阿尔萨斯的体内。"}}
D.SpellTexts[72591]={Aura={["979997f4ce4e183b:8"]=S[13681]}}
D.SpellTexts[72594]={Description={["16be060ba170889a:33"]="将邪恶之力导入阿尔萨斯的体内。"}}
D.SpellTexts[72595]={Description={["2c9127566d2e193b:57"]="召回目标的灵魂，使其复活。"}}
D.SpellTexts[72598]={Description={["29f69cdae12e24ef:32"]="将冰霜之力导入阿尔萨斯的体内。"}}
D.SpellTexts[72599]={Description={["f0b05e4f834d14be:36"]="将英格维的躯体拖到蓝色大篝火处。"},Aura={["f0b05e4f834d14be:36"]="将英格维的躯体拖到蓝色大篝火处。"}}
D.SpellTexts[72649]={Description={["f49c6a5e0ea11ba3:75"]=S[22084]},Aura={["e90c41ed75fa5096:66"]="伤害提高。\r\n受到的伤害转而治疗施法者。\r\n攻击不会产生威胁值。"}}
D.SpellTexts[72659]={Description={["f5f7268f922b1c5e:50"]="扔出一块诱饵，尝试捉住一只异种群居蝎。"}}
D.SpellTexts[72681]={Aura={["d6b3916047f187c5:69"]="你抓住了一只异种蝎！在它把绳子咬断前把它带回营地。"}}
D.SpellTexts[72711]={Description={["3a3d87ccfe3abfa1:101"]="这是希尔瓦娜斯·风行者在吟唱“高等精灵的挽歌”时对自己施放的装饰光环。"}}
D.SpellTexts[72735]={Description={["89cd3f72d323345f:32"]="将死亡之力导入阿尔萨斯的体内。"}}
D.SpellTexts[72736]={Aura={["d66804c6d580ad69:58"]="控制你的哈扎里群居蝎进入巢穴的心脏地带，并将其引爆！"}}
D.SpellTexts[72741]={Description={["fe6b58c7ad5452ca:29"]="轰击袭击者。"}}
D.SpellTexts[72754]={Description={["ea698914735139e9:140"]="对效果范围内的所有敌人每秒造成暗影伤害。每有敌人受到该效果影响，效果的范围和伤害就会提升。持续60秒。"}}
D.SpellTexts[72755]={Description={["37cf3959e04cb6ba:29"]="把靠近的敌方船只轰沉。"}}
D.SpellTexts[72762]={Description={["adf7bf1360ba251e:114"]="污染一个随机目标脚下的区域。任何在此区域内的敌人都会遭受暗影伤害并使得这一区域进一步扩大。持续30秒。"}}
D.SpellTexts[72794]={Aura={["bb69b8cbd6c825f8:40"]="你正在遭受可怖的变形。"}}
D.SpellTexts[72807]={Description={["df7423571f668ed6:76"]="召唤或解散一头可供骑乘的缚寒冰霜征服者。这是一种飞行坐骑。"}}
D.SpellTexts[72808]={Description={["99c74446d6548c6f:79"]="召唤或解散一头可供骑乘的浴血冰霜征服者。这是一种飞行坐骑。"}}
D.SpellTexts[72839]={Aura={["5e98ab230a82ea56:81"]="这辆熊熊燃烧的投石车已受到损伤。过不了多久就会彻底报废。善加利用吧！"}}
D.SpellTexts[72840]={Description={["6fd575c2d7ecc965:58"]=S[13711]},Aura={["6fd575c2d7ecc965:58"]=S[13711]}}
D.SpellTexts[72849]={Description={["bb53277c183e19fb:33"]="让蝙蝠飞回吉尔尼斯城，并让它降落。"}}
D.SpellTexts[72853]={Description={["2622eddcaab60b89:64"]="将神圣供品放置在埃德里奇之墓前，让被打扰的灵魂安息。"}}
D.SpellTexts[72867]={Description={["8049b3802a07244b:83"]="死亡疫病认为它的宿主已经毫无价值，它将杀死宿主，离开躯体寻找一个更强大的宿主。"}}
D.SpellTexts[72870]={Aura={["4e02d9b81a035515:69"]="你被狼人咬伤了。伤口看起来不严重……也许会随着时间的推移逐渐愈合？"}}
D.SpellTexts[72872]={Aura={["5e383311cee97eec:46"]="伤口在不断恶化。你的感觉不太好。"}}
D.SpellTexts[72884]={Aura={["664d9d85d5af7ef0:45"]="暂时不能再度感染死亡疫病。"}}
D.SpellTexts[72887]={Aura={["4080e694d2f6cd4d:175"]="用超级助推火箭靴来消灭乌司坦的地精僵尸。某些技能和法术——如影响移动速度的火箭跳和冲锋，无法与火箭靴一同发生作用。"}}
D.SpellTexts[72891]={Description={["b57817526e668b75:70"]="发动你的超级助推火箭之靴，并烧掉这些地精僵尸。"}}
D.SpellTexts[72925]={Description={["b606dcb0792adf05:34"]="使一名受伤的防御者重装上阵。"}}
D.SpellTexts[72935]={Description={["13ba51f416ab1017:119"]="让目标陷入一股无法逃脱的旋风中，灵魂被吸走，变成一个无意识的僵尸！"},Aura={["73f8608ad82d8c09:37"]="被困住！正在转变为僵尸！"}}
D.SpellTexts[72940]={Description={["3d4e116ea43a9ed7:51"]="向附近的一个怒吼投石车或掷刀车投掷一把火炬。"}}
D.SpellTexts[72944]={Description={["930810e90e49a4f8:15"]="消灭僵尸！"}}
D.SpellTexts[72957]={Description={["cf9ae50be6467816:68"]=S[5418]}}
D.SpellTexts[72971]={Description={["b850d2ef231b7e32:82"]="跳进火山口，并将这双靴子交给霍巴特·钩锤。适合单程旅行。"},Aura={["d7fa16e59cd14cf2:34"]="真是地精工艺的奇迹！"}}
D.SpellTexts[72975]={Aura={["f836c1402bab6247:48"]="巴斯东的黑暗能量包围并保护着怒吼。"}}
D.SpellTexts[72976]={Aura={["bc317139ec642b28:95"]="你正在遥控一只被控制意识的爬虫。将它引入哈扎里蜂巢深处，然后引爆！"}}
D.SpellTexts[72984]={Description={["f36ea5a69a28c07f:32"]="把自己伪装成砂槌食人魔"},Aura={["db524c498beaa652:32"]="草草伪装成一个砂槌食人魔。"}}
D.SpellTexts[72996]={Rank={["1044fc4216ed2ac5:5"]=S[17700]}}
D.SpellTexts[72998]={Aura={["2f4f142ba693da90:109"]="被包裹在暗影牢笼能量之中的敌人如果移动，就会每秒受到递增的暗影伤害。"}}
D.SpellTexts[73004]={Description={["fe6744e35e497f14:58"]="使一个目标昏迷，让他无法行动，但也不会受任何伤害。"},Aura={["9be1d5dd4fb88fa6:75"]="被禁锢在冰块中，无法攻击、移动和使用法术。对所有攻击和法术免疫。"}}
D.SpellTexts[73016]={Description={["20b82166dd8a0d0b:24"]="装饰火焰吐息法术。"}}
D.SpellTexts[73068]={Description={["cca32f34dc32ed97:68"]="将赠送餐点扔给砂槌食人魔。被投掷餐点的食人魔首先必须被削弱。"}}
D.SpellTexts[73070]={Aura={["70a0394296a9e2bd:14"]=S[6323]}}
D.SpellTexts[73075]={Description={["e4c1cb579e6ea368:74"]=S[6242]}}
D.SpellTexts[73079]={Description={["a9d4b78e15af2185:45"]=S[9259]}}
D.SpellTexts[73082]={Description={["c5cc4b5289865df1:65"]="向目标区域派出辐射计量仪来测量辐射能级。"}}
D.SpellTexts[73090]={Aura={["bda7d4804dc1906d:55"]="火山爆发啦！快去找莎希，尽快离开这儿！！！"}}
D.SpellTexts[73094]={Description={["fe20b3ca54c7eac1:40"]="向艾斯特蕾·沃斯展示她在镜子中的倒影。"}}
D.SpellTexts[73108]={Description={["5205ba6c1a2b6411:36"]="用套索套住受伤的邪鳍鱼人。"}}
D.SpellTexts[73133]={Description={["e9c915f01cc56061:82"]="恐吓所有附近的邪鳞鱼人蝌蚪。使用3次之后，鱼人蝌蚪将因恐惧而崩溃。"},Aura={["6015c10070c10301:80"]="这个鱼人蝌蚪被入侵者恐吓住了。使用3次之后，它将因恐惧而崩溃。"}}
D.SpellTexts[73137]={Aura={["0f6069d391e14bb0:66"]="你救了那些地精。现在莎希会来救你。奋力坚持住！"}}
D.SpellTexts[73141]={Description={["8e1dd7f95455e4c8:53"]="对三瓣牙使用蔓延之能，该过程需引导。"}}
D.SpellTexts[73155]={Aura={["c73caeb36c55d434:73"]="因大地的陡然崩裂和释放出的可怖生长力而晕眩。"}}
D.SpellTexts[73162]={Description={["8fd00482f5e48fc3:49"]=S[1606]},Aura={["8fd00482f5e48fc3:49"]=S[1606]}}
D.SpellTexts[73175]={Description={["cf9ae50be6467816:68"]=S[5418]}}
D.SpellTexts[73207]={Description={["cffb97e69be72bf1:58"]="用嗅觉在空气中捕捉信息素，以此找到通向虫巢的路。"}}
D.SpellTexts[73211]={Description={["e9d7c51bbda60a16:63"]="引爆异种蝎的炸药。为此，你必须深入哈扎里蜂巢。"}}
D.SpellTexts[73257]={Description={["384c2e812db328f0:65"]="将一枚大炸弹扔向靠近冲击点的任何南海封锁者。"}}
D.SpellTexts[73287]={Description={["434272297a2ca1f0:49"]="将诱灵蜡烛放置在莉莉丝的晚餐桌上。"}}
D.SpellTexts[73290]={Description={["cbdc0d2debe46842:105"]="这个美丽雕像的两只眼睛都没有了。如果你能把丢失的2枚地狱炎石安装回去，它的魔法就会恢复。"}}
