D.SpellTexts[74567]={Description={["dcdf9e9a39579ef5:222"]="在一名敌对目标脚下打下燃烧印记。燃烧效果消失或被驱散时会引发爆炸，点燃出一片火焰之地，火焰之地的大小取决于爆炸时吞噬效果叠加的层数。该效果可以被清除诅咒或清除魔法类法术驱散。"},Aura={["17793106a2a5e8dd:65"]="当炽焰燃烧效果被移除后，提高施放出的潜在能量。"}}
