D.SpellTexts[74795]={Description={["eb5fa70e4341729f:225"]="在一名敌对目标身上打下吞噬印记。当吞噬印记效果消失或被驱散时会引发爆炸，点燃出一片火焰之地，火焰之地的大小取决于爆炸时吞噬效果叠加的层数。该效果可以被清除诅咒或清除魔法类法术驱散。"},Aura={["9a8db766808eab69:65"]="当灵魂吞噬效果被移除后，提高施放出的潜在能量。"}}
