D.SpellTexts[74886]={Aura={["7fc39df654c007d3:33"]="透过伯纳德双眼看到的一切。"}}
D.SpellTexts[74890]={Description={["85ec527d38b58dc6:30"]="变为一尊英武的个人雕像。"}}
