D.SpellTexts[74932]={Description={["0afb26644a0d4747:48"]="右键点击来召唤或解散你的霜娃娃。"}}
D.SpellTexts[74934]={Description={["a310997ec649b3bd:67"]="如果你的听众兴致乏乏，那么你就需要一点鼓舞人心的演讲。"}}
D.SpellTexts[74935]={Description={["082a746f2bd846d2:54"]="如果你的听众很愤怒，就把他们的这股怒火导向战斗吧！"}}
D.SpellTexts[74937]={Description={["cd35c711245fd9e2:46"]="这些人都疯了。你需要适应这种情况。"}}
D.SpellTexts[74938]={Description={["f2c308e8868645c3:19"]=S[2682]},Aura={["f2c308e8868645c3:19"]=S[2682]}}
D.SpellTexts[74947]={Description={["373353d3808cc0f8:20"]="别讲话了。"}}
