D.SpellTexts[74960]={Aura={["565154d18fab16c0:26"]="你被冻住了！"}}
D.SpellTexts[74966]={Description={["c0e8d2300dfe36df:23"]="全都上了疯狂的火车！"}}
D.SpellTexts[74974]={Description={["251e8c43a80d0896:17"]="从树上往下爬。"}}
D.SpellTexts[74975]={Aura={["f7abd8c8bda20acb:46"]="你的钱包丢了……等等，你根本就没有钱包……"}}
D.SpellTexts[74977]={Description={["6d71ffff3dcbed64:98"]="将一只被瓦妮拉施法的青蛙丢到回音群岛上的某一个闪光点上。只能在骑乘蝙蝠时使用。"}}
