D.SpellTexts[86678]={Description={["1e62fa950be1f29e:49"]="为你治疗的目标进行治疗，其治疗量相当于你造成的治疗效果的30%。"}}
D.SpellTexts[86686]={Aura={["491d68cfb93351f8:60"]="你正在空中飞行……真不舒服！希望降落伞管用……"}}
