D.SpellTexts[86717]={Description={["17e5b39895ea25d1:35"]="射击一名敌人，造成火焰伤害。"}}
D.SpellTexts[86724]={Description={["81d270e666d4226b:24"]="更狠。更快。更强。"},Aura={["81d270e666d4226b:24"]="更狠。更快。更强。"}}
D.SpellTexts[86728]={Description={["a9472e809da2e6d5:52"]="吸取一个敌人的生命，并将其转化给施法者。"}}
D.SpellTexts[86734]={Aura={["615de33e519aaddd:17"]=S[19916]}}
D.SpellTexts[86735]={Description={["301bf7fd26388c40:39"]="见习萨满“金矿”在这……呃，藏好了！"},Aura={["9f9aa87d03eb81d0:25"]="确保见习萨满“金矿”的安全。"}}
D.SpellTexts[86740]={Aura={["979997f4ce4e183b:8"]=S[13681]}}
D.SpellTexts[86762]={Description={["dcadd7368bdca2b3:42"]="搜查一名暴风城市民，在他身上寻找邪教物品。"},Aura={["dcadd7368bdca2b3:42"]=S[12534]}}
D.SpellTexts[86766]={Description={["f7c245753cdef54e:59"]="吞噬一个法术，使其吸收它的魔法后反射回施法者。"},Aura={["070d57ef1f28027a:46"]="吸收一次魔法攻击，并将其反射回施法者。"}}
D.SpellTexts[86767]={Description={["b9f4cf6638be93df:44"]="在暴风城大门处朗读国王的宣告。"}}
D.SpellTexts[86780]={Description={["e6645c5fb437a170:19"]="囚禁目标。"},Aura={["a7d53af4efd68e77:27"]="被暗影牢笼围困。"}}
D.SpellTexts[86785]={Aura={["8a42fbd25516e981:71"]="每秒造成一次伤害。\r\n如果吸收过多水银将会变形。"}}
D.SpellTexts[86790]={Aura={["78c1d3ea57792ead:9"]=S[20345]}}
D.SpellTexts[86798]={Description={["057cbdefa9538020:56"]=S[9072]}}
D.SpellTexts[86804]={Description={["f1c7c7f3c97061f0:23"]="将某个人向你拖过来。"}}
D.SpellTexts[86806]={Description={["575e81cc1d16acaf:53"]="对周围的所有敌人造成自然伤害，并将其击退。"}}
D.SpellTexts[86814]={Aura={["979997f4ce4e183b:8"]=S[13681]}}
D.SpellTexts[86817]={Aura={["ca3cd7bf7fc5c818:19"]="吸收魔法伤害。"}}
D.SpellTexts[86818]={Description={["fda0ed7421811907:27"]="使用裁缝制造一件物品。"}}
D.SpellTexts[86819]={Description={["757f5ebf7f194afe:58"]="用火焰烧灼目标，对附近的一切敌人造成火焰伤害。"},Aura={["eb4cd748f7742d2b:27"]=S[15444]}}
D.SpellTexts[86829]={Description={["2855f7d811eda4fb:52"]="使受到的伤害提高500%，攻击速度降低80%。"},Aura={["2855f7d811eda4fb:52"]="受到的伤害提高500%，攻击速度降低80%。"}}
D.SpellTexts[86830]={Description={["e4b792916499c14a:211"]="以魔王的力量发动打击，这种力量完全无法形容。但凡受到打击的目标，双眼会被毁灭光芒灼瞎。他们致死也无法明白自己到底承受了怎样的法术。"}}
D.SpellTexts[86839]={Description={["06e0ae59b01651a6:37"]="逮捕一个在暴风城的邪教渗透者。"}}
D.SpellTexts[86845]={Description={["686c5b1924724850:101"]=S[5682]}}
D.SpellTexts[86857]={Description={["f4ecb5e44dd6bedb:204"]="如果说矮人最喜欢的是什么，那一定是喝酒。接下来就是战斗。或者是二者兼而有之。\r\n\r\n这个杯子属于一个小小的贵族或者富有的商人。它很沉重，足以打破某个人的脑壳。上面留下的痕迹表明它很可能被这样使用过。"}}
D.SpellTexts[86864]={Description={["c1d5ee17ffb5e954:215"]="一些矮人将他们的逝者安放在坟墓里。但与亡灵打过交道的矮人都习惯火化他们的死者。这只骨灰坛已经碎裂了，其中的骨灰早已漏尽。在坛底以清晰的矮人字体印着“雷霆箭”。"}}
D.SpellTexts[86865]={Description={["c79f39dbf093eb2c:100"]="这件武器的刃上有许多缺口。它的握柄是用鹿角或羊角做成的。靠近握柄末端的地方雕刻着“W. G.”两个大写字母。"}}
D.SpellTexts[86866]={Description={["018ca8e10f119230:167"]="矮人喜欢金子也喜欢喝酒，而赌博的时候自然而然两者兼备。这些骰子应该是用绵羊骨头雕成的。有几面还能看见未擦净的血迹。"}}
D.SpellTexts[86873]={Description={["c4aa8c761636298f:98"]="开启火焰传送门控制器，将你和见习萨满“金矿”传送到源质深渊入口。"}}
D.SpellTexts[86887]={Description={["6975dd30c36c8349:28"]="教你学会一种珠宝加工设计。"},Aura={["6975dd30c36c8349:28"]="教你学会一种珠宝加工设计。"}}
D.SpellTexts[86889]={Description={["59cdb6d5ab014824:30"]="教你学会一种制皮图样。"},Aura={["59cdb6d5ab014824:30"]="教你学会一种制皮图样。"}}
D.SpellTexts[86891]={Description={["70c6a96a103d87c9:25"]="教你学会一种附魔设计。"},Aura={["70c6a96a103d87c9:25"]="教你学会一种附魔设计。"}}
D.SpellTexts[86911]={Description={["20292831a4a25944:87"]="使阿萨德进行引导以制造一个接地场，确保他从天空召唤闪电时的安全。"}}
D.SpellTexts[86918]={Description={["5015c9856350826a:28"]=S[5608]}}
D.SpellTexts[86938]={Aura={["3ad612b031a230ff:72"]=S[4775]}}
D.SpellTexts[86939]={Description={["d39840edd69a8286:123"]="仔细阅读一位资深冒险家的经历。如果你还需要学习一些知识（低于85级），那么你很可能会在这次阅读中得到莫大的好处。"}}
D.SpellTexts[86973]={Description={["6f10eb885919ed13:49"]="冬拥湖上空的气流相当稳定，可以进行正常飞行。"},Aura={["415ae8c47041eff9:38"]="你可以安全地飞行，直到下一个飞行光环。"}}
D.SpellTexts[86986]={Description={["9ed30dbe69c9498d:42"]=S[7644]}}
D.SpellTexts[86988]={Aura={["b91d045db6c1824e:111"]="你刚刚读了一则197页的故事，讲述两个治疗者之间的决斗。当你对敌人造成伤害时，你有一定几率进行自我治疗。"}}
D.SpellTexts[87020]={Description={["1f10d571dad25794:59"]="放置一台全息影像放映机，吸引附近被诅咒的工程师注意。"}}
D.SpellTexts[87024]={Aura={["d44f6764a6d551f9:65"]="你刚刚触发过灸灼效果，短时间内无法再次触发。"}}
D.SpellTexts[87026]={Description={["ed29d73d955a5b32:58"]="在三个教派祭坛的附近分别朗诵传送门仪式咒语。"}}
D.SpellTexts[87028]={Description={["3ed483554f28c21c:25"]="使用烹饪制造一件物品。"}}
D.SpellTexts[87030]={Description={["36f59f47e5e4055e:37"]="对入侵的穴居人造成大量火焰伤害。"}}
D.SpellTexts[87034]={Description={["b8fd6f0802ccb19d:46"]="向近处的穴居人射出一股电流。"}}
D.SpellTexts[87066]={Description={["82fe315a732befc9:16"]="附魔一个物品。"}}
D.SpellTexts[87067]={Description={["3b8be8ec24ccfd77:18"]="分解一个物品"}}
D.SpellTexts[87071]={Description={["632bbecef6239915:25"]="使用炼金术制造一件物品。"}}
D.SpellTexts[87077]={Description={["864b7db515aa598a:24"]="剥取一只动物的皮。"}}
D.SpellTexts[87084]={Description={["0839d739a361a4a4:44"]="生成三只小蜘蛛，帮助施法者战斗。"}}
D.SpellTexts[87090]={Description={["3ea9639fa761c1e0:40"]="召唤或解散一个可供骑乘的地精三轮摩托。"}}
D.SpellTexts[87091]={Description={["37a7284040b89d1d:38"]="召唤或解散一辆地精三轮摩托涡轮增压型。"}}
D.SpellTexts[87094]={Description={["f32449e167b9b910:41"]="使聚变核心在2秒内的移动速度提高。"},Aura={["9968ba36d8d60369:28"]="2秒内的移动速度提高。"}}
D.SpellTexts[87140]={Description={["7a172c2f3509c494:48"]="在奥格瑞玛的大门处阅读酋长的宣告。"}}
D.SpellTexts[87142]={Description={["9ed30dbe69c9498d:42"]=S[7644]}}
