D.SpellTexts[87204]={Aura={["5077a842d269ba59:16"]=S[6323]}}
D.SpellTexts[87214]={Description={["5b524dfc50eb558b:20"]="升起一面联盟军旗。"},Aura={["9927d2d5a6881310:30"]="代表联盟的颜色。"}}
