D.SpellTexts[88180]={Description={["fbed177ffc060a70:185"]="狮鹫一直以来都是蛮锤矮人的盟友，他们把这种高贵的坐骑带给了联盟其它部族。这个精美的小雕像是用雪花石膏雕刻的。雕像锋利的爪子足以割开皮革。"}}
