D.SpellTexts[88262]={Description={["4708b9475645ee94:141"]="几乎无人知晓巨魔的巫毒术起源于什么时候。巨魔的信仰很复杂，充满了黑暗的灵魂，以及那些原始又带有动物特征的造物主，他们将其视若神明。"}}
D.SpellTexts[88264]={Description={["5a7ec0e8893f7ee7:90"]="向一个敌人掷出黏性炸弹，它会在几秒钟内做好起爆准备，如果有敌人在附近，就会爆炸。"}}
