D.SpellTexts[88320]={Description={["73052a03dc5d24b8:45"]="从一个睡着的黑铁锻造师身上拾取物品。"},Aura={["ce71f2a2dac3babb:57"]="隆克正携带着从黑铁锻造师拿到的物品。"}}
D.SpellTexts[88323]={Aura={["691d5e245ab05485:21"]="真大。简直是巨大啊。"}}
D.SpellTexts[88330]={Aura={["8e7dd0ac639ec311:53"]="你的口袋里装了小鬼！把他带给奥术师德拉莉丝！"}}
