D.SpellTexts[88352]={Description={["8889729b0ab0c9d2:135"]="你的胸前绑着一枚炸弹！当计时器走完的时候，猛烈的爆炸将对你身边所有盟友造成严重的火焰伤害，并将目标炸上半空。"},Aura={["1bdd8e1b3f0e5c22:103"]="当计时器走完的时候，猛烈的爆炸将对你身边所有盟友造成严重的火焰伤害，并将目标炸上半空。"}}
D.SpellTexts[88354]={Description={["3a33faa53e9aa0d0:41"]="当小鬼被削弱之后用袋子将其抓获。"}}
D.SpellTexts[88361]={Description={["f9af3150cd1ddc13:30"]="他肩上扛着一大块木头。"},Aura={["f9af3150cd1ddc13:30"]="他肩上扛着一大块木头。"}}
