D.SpellTexts[88401]={Description={["22b42b59d4cdd7ea:26"]="受到的伤害降低50%。"},Aura={["22b42b59d4cdd7ea:26"]="受到的伤害降低50%。"}}
D.SpellTexts[88409]={Description={["457f374977a1fc76:48"]="召唤地精小队降落并帮助你。"}}
D.SpellTexts[88418]={Description={["bde1a7575fa93cd8:87"]="从火元素的体内收集一份样本。必须在元素存活时收集样本。"}}
