D.SpellTexts[88423]={Description={["45918cf8c89d0537:79"]="净化盟友目标，移除所有魔法、诅咒和中毒效果。"}}
D.SpellTexts[88427]={Description={["b590b0f6b082e655:207"]="引导一股电流注入施法者当前目标的体内，造成越来越强的自然伤害。只有当施法者无法对目标进行近战攻击时，这一技能才会有效。如果目标进入施法者的近战攻击范围，技能便会结束。"},Aura={["77af14585b1c0231:36"]=S[20630]}}
D.SpellTexts[88434]={Description={["6226699de90956b0:25"]="开启以搜寻碎片。"}}
D.SpellTexts[88438]={Description={["ed6c32ebc43e0790:117"]="在匿影山变形进入虚空，使你可以看清那里的真实模样。你必须站在提克迪奥斯的魔印上才能使用。"},Aura={["79b8549ff2f60e86:68"]="在匿影山变形进入虚空。不要离开匿影山。"}}
D.SpellTexts[88439]={Description={["958fdfdd78a48024:60"]="召唤一个被束缚的震地者跟随施法者，直到解散。"}}
