D.SpellTexts[88862]={Description={["3b4116c0c9330171:22"]="召唤邪恶水蛭。"}}
D.SpellTexts[88867]={Description={["3d04ea81d181b6c6:54"]="使施法者的血液石化，消除所有有害效果。"}}
D.SpellTexts[88872]={Description={["15a9438a6e1b996f:72"]="当奇美隆的几个脑袋在争斗时，他无法发动近战攻击。"},Aura={["eb05ad1be02b18e4:28"]="无法发动近战攻击。"}}
