D.SpellTexts[88893]={Rank={["3ee7310dd154b3dc:7"]="升级"}}
D.SpellTexts[88907]={Description={["6e4bae6be4564164:157"]="希里克是南部巨魔膜拜的动物之魂。希里克的动物图腾是蝙蝠。赞达拉的高阶祭司耶克里克是希里克最有名望的信徒之一。"}}
D.SpellTexts[88908]={Description={["15c0d17436ecfe99:88"]="这是个小小足部标本，来自丛林蜥蜴。它曾经具有的任何魔法都早已被吸走。"}}
D.SpellTexts[88909]={Description={["79552742879836e1:150"]="一个用橡木雕刻出的哨子。可能是用来召唤宠物或者坐骑，也有可能是孩子的玩具。看样子，它被某种动物或者是矮人的小孩含咬过不短的时间。"}}
D.SpellTexts[88910]={Description={["f52f8390d8ecda89:188"]="莫迪姆斯·安威玛尔在三锤之战前曾是矮人的高山之王，铁炉堡的大门口耸立着他的巨大雕像。这个铜质带扣可能属于他的某个贴身侍卫或仆人。"}}
D.SpellTexts[88911]={Description={["54ec723fd29eda12:66"]=S[1863]},Aura={["54ec723fd29eda12:66"]=S[1863]}}
D.SpellTexts[88913]={Aura={["9a98b54eadd5b4ff:35"]="召唤至野性之心哨站的传送门。"}}
D.SpellTexts[88914]={Description={["7be7aff2bf488369:116"]="使用你的锁链钩子，钩住一头经过的黑曜石火翼龙。也可以用在友方龙身上，只是会让他们非常不高兴。"}}
D.SpellTexts[88928]={Description={["f536fd8d822b62d6:44"]="瞄准畸怒邪灵，消除他的保护盾。"}}
D.SpellTexts[88929]={Description={["eba7c44c6d0a382f:148"]="三叶虫曾一度分支众多，数量巨大，遍布艾泽拉斯。只是早已灭绝了。但有传闻说现在还存活着巨大体型的三叶虫。"}}
D.SpellTexts[88930]={Description={["bd41dd592c724aae:176"]="蕨类是种原始的植物，有茎、叶和根，而无种子，不具花。其以孢子繁殖，与蘑菇类似。在远古时代，蕨在生物链中的地位与今日的有花植物一样。"}}
D.SpellTexts[88961]={Description={["379a00e04749172b:96"]="考古学家可以收集神器碎片，并将这些碎片拼合成完整的古代神器，可达到的技能上限为150点。"}}
D.SpellTexts[88963]={Description={["0899f8aad723d17d:50"]=S[2419]}}
D.SpellTexts[88972]={Description={["a086968951948220:102"]=S[20690]},Aura={["a086968951948220:102"]=S[20690]}}
D.SpellTexts[88981]={Description={["e6cf2440bda7f8b3:44"]="你行走在生者与亡者共存的世界。"},Aura={["e6cf2440bda7f8b3:44"]="你行走在生者与亡者共存的世界。"}}
D.SpellTexts[88983]={Description={["1d4fe1ad94a2feba:94"]="激活灵魂之光，摧毁区域内的任何邪恶灵魂。必须在灵魂世界才能使用。"},Aura={["01203e3744edcc68:24"]="开启灵魂之光。"}}
D.SpellTexts[88986]={Description={["a5d7e1a38b5aa892:33"]="击中后造成范围火焰伤害。"}}
D.SpellTexts[88990]={Description={["ec6066814feb7028:59"]="召唤或解散一个可供骑乘的暗色凤凰。这是一种飞行坐骑。"}}
D.SpellTexts[89008]={Description={["163f4ab5c1bd7ae6:56"]="在黑曜石之卵上释放母神之焰，迫使其孵化。"}}
D.SpellTexts[89009]={Description={["b9b14622e208e41b:175"]="一个精致小巧的瓷盒，似乎是用来收纳首饰珠宝或者上层女精灵的其它小物品。瓷盒的锁扣是白银的，看上去像是两枚橡果和一片冬青叶。"}}
D.SpellTexts[89012]={Description={["cc73d7304aa11b21:205"]="虽然大多数值钱的珠宝都已丢失，这个装饰精美的物品在过去也算是个小宝贝了。它的一侧还镶嵌着一串细小的鹦鹉螺，另一侧则有一段铭文——“无尽的哀伤，永失萨纳拉”。"}}
D.SpellTexts[89014]={Description={["26ffbe36bde16afd:120"]="这块布袍织得非常细致，可能是用蛛丝织就的。银白色的袍子在光照下会发生细微的颜色变化。"}}
D.SpellTexts[89022]={Description={["70375da1462c9738:58"]="用在暗影耐格什身上，让他在被你杀死之后在活转回来。"}}
D.SpellTexts[89034]={Description={["e26b51d08b1ef143:44"]="使你目标的最高物品等级与你相同。"}}
D.SpellTexts[89035]={Description={["beb132cd02eecb48:35"]="暂时无法进入大洞。"}}
D.SpellTexts[89037]={Description={["bfbc98002ae93e7b:35"]="暂时无法进入恶魔监狱。"}}
D.SpellTexts[89038]={Description={["4f8c50f2f5301cb7:40"]="现在无法进入咒怨地牢。"}}
D.SpellTexts[89039]={Description={["05f18d5216747719:48"]="右键点击以召唤或解散你的暗色凤凰宝宝。"}}
D.SpellTexts[89040]={Description={["979ac799b037feee:38"]="净化黑曜石之树下的洞穴。"}}
D.SpellTexts[89051]={Description={["ecd50f75409e81e2:115"]=S[3684]}}
D.SpellTexts[89054]={Description={["169248fdc6e976bc:31"]="放下你的托尔巴拉德探照灯。"}}
D.SpellTexts[89089]={Description={["868b73b724ab6c00:55"]="用铲子拔出食人花苗。不要做错了，朋友！"}}
D.SpellTexts[89104]={Aura={["5da75f750e9ea49c:31"]="被卷入无情风暴中！"}}
D.SpellTexts[89115]={Description={["19c78cdf4ec93de0:7"]="轰！"},Aura={["19c78cdf4ec93de0:7"]="轰！"}}
D.SpellTexts[89119]={Description={["2d10b1dcd47eb039:48"]="解除玩家坐騎，將其擊退，並給予擊殺獎勵。"}}
D.SpellTexts[89128]={Description={["94b85cd7bb7ec39c:39"]="车辆的速度大大提高了。"},Aura={["94b85cd7bb7ec39c:39"]="车辆的速度大大提高了。"}}
D.SpellTexts[89131]={Description={["75fc136af54e922d:48"]=S[6034]},Aura={["75fc136af54e922d:48"]=S[6034]}}
