D.SpellTexts[89140]={Aura={["5e9b98d3c751b962:54"]="该效果消失前不会再触发恶魔重生。"}}
D.SpellTexts[89142]={Aura={["3a8048aa26023407:45"]="你也许需要重新思考一下“正确”这个词的真正定义是什么。"}}
D.SpellTexts[89145]={Description={["dc6afd2a9e2436c7:62"]="解锁第7个公会银行标签。该物品只能由公会领袖使用。"}}
D.SpellTexts[89146]={Description={["f57df6d9594d7254:63"]="解锁第8个公会银行标签。该物品只能由公会领袖使用。"}}
D.SpellTexts[89151]={Description={["b2c2afe2cb0bc777:78"]="戴上这只眼罩，你就能看到伪装的恶魔。你只能在碧火小径使用它。"},Aura={["67b53c23b285fd6a:39"]="你能看穿伪装的恶魔的真面目。"}}
