D.SpellTexts[89188]={Description={["3106b3f1cbb67ea8:28"]="放出一小群甲虫。"}}
D.SpellTexts[89200]={Description={["da1793767182fd55:42"]="对附近的死神原型机造成自然伤害。"},Aura={["da1793767182fd55:42"]="对附近的死神原型机造成自然伤害。"}}
D.SpellTexts[89201]={Description={["8e0772ead1b45e7f:13"]="创造一块岩石。"}}
D.SpellTexts[89210]={Description={["a02791c0316d82fb:40"]="米尔拉的迅速反应减慢了你的坠落。"},Aura={["a02791c0316d82fb:40"]="米尔拉的迅速反应减慢了你的坠落。"}}
