D.SpellTexts[89226]={Description={["ec6aee1126bc0f26:55"]="厄索拉斯之血凶猛地净化外来体。"}}
D.SpellTexts[89228]={Description={["059c0284215f3a0b:52"]="涌向厄索拉斯中心，净化外来体。"},Aura={["059c0284215f3a0b:52"]="涌向厄索拉斯中心，净化外来体。"}}
