D.SpellTexts[89255]={Description={["f6fadbf57abfe9b4:19"]="穿上食人魔衣着。"},Aura={["f2e55cc1da823eb2:30"]="你伪装成火腹食人魔。"}}
D.SpellTexts[89257]={Description={["eac931f54c8a5158:20"]="穿上地精衣着。"},Aura={["7f6e763ff197b56e:34"]="你伪装成地精雇佣兵。"}}
