D.SpellTexts[89261]={Description={["c74396cb7741bfd8:52"]="将你伪装成黑石兽人的爪牙。"}}
D.SpellTexts[89263]={Description={["de685bd8c413c2db:58"]=S[5809]}}
D.SpellTexts[89281]={Description={["669a83496e3f0a98:34"]="一种安静的姿态，适合追踪猎物。"},Aura={["c5a15ae01e76b433:16"]="追踪猎物。"}}
