D.SpellTexts[89297]={Description={["2253335c98970a3f:70"]="向温娜·哈萨德展示这只耳朵，吸引她的注意力，将她从软泥中拖出来。"}}
D.SpellTexts[89314]={Description={["78a855f7fa9a589a:52"]="在群星密室里为泰坦的装置进行充能。"}}
