D.SpellTexts[89415]={Description={["aba93d3a70e945d3:49"]="幼龙向面前锥形区域内喷放闪电。"}}
D.SpellTexts[89421]={Description={["e9f3dd1df1f29502:95"]="造成越来越强的暗影伤害。当此效果被驱散时，它会弹射至目标玩家附近的两名盟友身上。"}}
D.SpellTexts[89425]={Aura={["b1125c515275c976:21"]="无法施法或攻击。"}}
D.SpellTexts[89431]={Description={["6cd15ff57403adc6:30"]="猛击一堆小贼！"}}
D.SpellTexts[89447]={Description={["5208e007b90c2320:44"]="刺在一个黑石兽人的背上。"}}
D.SpellTexts[89460]={Description={["a562a1531cf50720:41"]="将施法者传送至托维尔失落之城。"}}
D.SpellTexts[89472]={Description={["ee03e864a338a113:45"]="点击右键，召唤或解散一只洛斯贝格海鸥。"}}
D.SpellTexts[89477]={Description={["d3a3e5e204c4bf91:45"]="向附近的黑石作战科多兽发出返回营地的信号。"},Aura={["0a061b6a103dd37f:42"]="这头科多兽已经被指引返回营地。"}}
D.SpellTexts[89496]={Description={["480f27f2ab3a09eb:51"]="暂时反转你的重力场。无法在战斗中使用。"}}
D.SpellTexts[89497]={Description={["aa764f3b9f58aef8:32"]=S[9109]}}
D.SpellTexts[89502]={Aura={["03b795600b4c9dcb:67"]="你的侏儒重力井已经过热，必须等到温度下降后才会起作用。"}}
D.SpellTexts[89507]={Description={["aa764f3b9f58aef8:32"]=S[9109]}}
D.SpellTexts[89513]={Description={["8d97e2009970f62d:39"]="让石头飞向空中，击打死亡之翼。"},Aura={["8d97e2009970f62d:39"]="让石头飞向空中，击打死亡之翼。"}}
D.SpellTexts[89516]={Description={["9960f9795d895f30:31"]="向一名敌人冲锋，将它击退。"}}
D.SpellTexts[89520]={Description={["218047d7daca10f2:31"]="骑上或停放一辆迷你地精改装车。"}}
D.SpellTexts[89530]={Description={["dce66a577cf397a0:30"]="一阵来自海上的飓风造成冰霜伤害。"},Aura={["dce66a577cf397a0:30"]="一阵来自海上的飓风造成冰霜伤害。"}}
D.SpellTexts[89555]={Description={["c4f9d950075d15d7:124"]=S[5794]},Aura={["b9c4740f44210518:33"]="近战攻击能够造成一次额外的攻击。"}}
D.SpellTexts[89557]={Description={["e2311260f8fa0251:41"]="向一头龙喉黑色幼龙射出一支火焰长矛。"}}
D.SpellTexts[89562]={Description={["e630470f64b50932:90"]="在荣耀之地训诫一名黑石兽人、火腹食人魔、燃棘巨魔或地精佣兵。"}}
D.SpellTexts[89566]={Description={["a5120071d7af18ca:29"]=S[19673]},Aura={["a5120071d7af18ca:29"]=S[19673]}}
D.SpellTexts[89568]={Aura={["5d2f7e418be2d202:20"]="新近受训过。"}}
D.SpellTexts[89570]={Description={["1a359d377a1a30d4:39"]="将萨赫特的狮子移动到当前位置。"}}
D.SpellTexts[89582]={Description={["d6565716c2401edb:17"]="吞噬它的猎物。"},Aura={["d6565716c2401edb:17"]="吞噬它的猎物。"}}
D.SpellTexts[89596]={Description={["a8538c72a282afd5:33"]="移除玩家的黑石伪装。"}}
D.SpellTexts[89597]={Description={["202be1ee439c6b2d:46"]="将施法者传送到托尔巴拉德的巴拉丁营地。"}}
D.SpellTexts[89598]={Description={["dbf70638469900ff:48"]="将施法者传送到托尔巴拉德的地狱咆哮之握。"}}
