D.SpellTexts[89622]={Description={["d662151aeae7d6bd:33"]=S[5332]}}
D.SpellTexts[89629]={Description={["6db932972d7cdcfa:39"]="借助混乱之水与死亡之翼战斗。"},Aura={["6db932972d7cdcfa:39"]="借助混乱之水与死亡之翼战斗。"}}
D.SpellTexts[89630]={Description={["65889c563d503717:43"]="以闪电和雷霆轰击死亡之翼。"},Aura={["65889c563d503717:43"]="以闪电和雷霆轰击死亡之翼。"}}
D.SpellTexts[89631]={Description={["9ec48e83c0a98ff2:43"]="以元素的愤怒撕裂死亡之翼。"},Aura={["9ec48e83c0a98ff2:43"]="以元素的愤怒撕裂死亡之翼。"}}
D.SpellTexts[89637]={Aura={["7a97507df9419860:42"]="瘫痪。任何伤害将打断该效果。"}}
D.SpellTexts[89645]={Aura={["bc7c4bb7f556b8bc:25"]="烈火烧灼。"}}
D.SpellTexts[89662]={Description={["2621b24eba9c3157:9"]="溺水中！"},Aura={["2621b24eba9c3157:9"]="溺水中！"}}
D.SpellTexts[89663]={Description={["4353a77320921a6a:71"]="对施法者面前的所有敌人进行轰击，造成火焰伤害。他们别想拿走这支蜡烛！"}}
D.SpellTexts[89668]={Aura={["3b29f62e696c23d5:33"]="你开始吸引闪电了。"}}
D.SpellTexts[89670]={Description={["00f286e138eb45fa:45"]="右键点击以召唤或解散你的犰狳幼崽。"}}
D.SpellTexts[89693]={Description={["0559b91fe2073488:154"]="当你通过某种可怕的魔法让这副小骷髅恢复如初的时候，这头幼兽突然活了起来。他是一只漂亮的好宠物。而且，因为他只是一副骨架，所以不会吃多少食物。"}}
D.SpellTexts[89696]={Description={["e592fcc3f3aa3472:115"]="经过涂漆抛光的木制披风挂扣被雕刻成牡鹿角的样子。在挂扣的内面刻着一个达纳苏斯语的名字：“派拉蒙德”。"}}
D.SpellTexts[89697]={Description={["ca9f8834f71f75af:67"]=S[5734]}}
D.SpellTexts[89701]={Description={["fa285d4bed922386:197"]="这只小雕像表现的可能是高阶祭司温诺希斯。不过各种类型的蛇一直都是巨魔文化的崇拜对象。这只雕像精致的下颚能够闭合。推测它可能被用来从手指上割取鲜血。"}}
D.SpellTexts[89702]={Description={["f4927cbb6182d07c:9"]="伪装。"},Aura={["33f18767a8d14dca:11"]="伪装。"}}
D.SpellTexts[89711]={Description={["d0a454da2929a341:171"]="这些羽毛可能来自于红绿金刚鹦鹉，不过它们都经过了精心的加工，可以持久保存。耳环上黄金的部分则被打制成荆刺和藤蔓的样子。而刺入耳垂的黄金尖钉只是看上一眼就会给人以特别的疼痛感。"}}
D.SpellTexts[89712]={Description={["a5120071d7af18ca:29"]=S[19673]},Aura={["979997f4ce4e183b:8"]=S[13681]}}
D.SpellTexts[89717]={Description={["9519a2425f4da7f5:167"]="仅就贪婪而言，除火拳之外的任何一位黑铁矮人之王与他相比都要自愧弗如。这只做工极尽精美奢华的酒杯肯定无数次在盛宴之中闪耀过夺目的光彩。但现在，它的一部分已经融化了。造成这种灾难的可能是熔岩，也可能是炽烈的龙息。"}}
D.SpellTexts[89718]={Description={["379a8123745abaa2:96"]="考古学家可以收集神器碎片，并将这些碎片拼合成完整的古代神器，可达到的技能上限为225点。"}}
D.SpellTexts[89719]={Description={["379b045da1e06b24:96"]="考古学家可以收集神器碎片，并将这些碎片拼合成完整的古代神器，可达到的技能上限为300点。"}}
D.SpellTexts[89720]={Description={["379b22c9a557d8e6:96"]="考古学家可以收集神器碎片，并将这些碎片拼合成完整的古代神器，可达到的技能上限为375点。"}}
D.SpellTexts[89721]={Description={["379ba603d2dd8968:96"]="考古学家可以收集神器碎片，并将这些碎片拼合成完整的古代神器，可达到的技能上限为450点。"}}
D.SpellTexts[89722]={Description={["379c2646ffef2cdf:96"]="考古学家可以收集神器碎片，并将这些碎片拼合成完整的古代神器，可达到的技能上限为525点。"}}
