D.SpellTexts[89745]={Rank={["9be076a0b7821de7:7"]="被动"}}
D.SpellTexts[89750]={Description={["dd540ac4222859ab:77"]="狂风平静下来，现在玩家能在风神王座中飞行了。"}}
D.SpellTexts[89751]={Rank={["d507c2749d1fa4b1:14"]=S[16475]}}
D.SpellTexts[89752]={Description={["9a99b2ad9f8769da:38"]="从枯萎软泥怪身上收集枯萎样本。"},Aura={["64f8c47dfca256f2:24"]="收集枯萎样本。"}}
D.SpellTexts[89756]={Aura={["d1f98ee4e8fccdf5:51"]="枯萎样本已耗竭。将随时间的推移自动恢复。"}}
D.SpellTexts[89766]={Rank={["d507c2749d1fa4b1:14"]=S[16475]}}
D.SpellTexts[89769]={Description={["1177f89c220d5e73:42"]="造成火焰伤害，并击倒附近的敌人。"},Aura={["979997f4ce4e183b:8"]=S[13681]}}
D.SpellTexts[89776]={Description={["3c43d145cf31707c:49"]="从死去的巨型灰烬座狼身上割下部位最好的一块肉。"}}
D.SpellTexts[89777]={Description={["07143c2ccace98a1:60"]="在黑石深渊的住宅区烧掉记录暮光教义的抄本。"}}
D.SpellTexts[89783]={Aura={["f2e601f8a8d1e2ef:34"]="粘稠的怒火等级1。适度愤怒。"}}
D.SpellTexts[89784]={Aura={["6f371690d6ca0057:33"]="粘稠的怒火等级2。不喜欢你。"}}
D.SpellTexts[89785]={Aura={["bb8abdb4237f1a99:34"]="粘稠的怒火等级3。杀！杀！杀！"}}
D.SpellTexts[89786]={Description={["5e0383d42a747f63:26"]="轰击供给船。"}}
D.SpellTexts[89792]={Description={["957401f2ffdf37db:47"]="逃向主人。逃跑可以解除一切昏迷和定身效果。"},Rank={["d507c2749d1fa4b1:14"]=S[16475]}}
D.SpellTexts[89798]={Description={["50b72d45bcce9f80:99"]="你清理掉了奈法利安最没用的怪物，他对你表示感激，并授予你一个新的头衔。"},Aura={["f57124aee8ff383b:35"]="谢谢你杀了我那些没用的爪牙！"}}
D.SpellTexts[89803]={Description={["a2c8990b1ea962b4:68"]="命令拉穆卡恒弓箭手向目标区域发射火箭。"}}
D.SpellTexts[89808]={Rank={["d507c2749d1fa4b1:14"]=S[16475]}}
D.SpellTexts[89809]={Description={["8ad895421e2ae671:82"]="向目标所在地点发射闪光弹簇，显示出区域内的所有刺枝潜伏者。"},Aura={["a733e08547ded8aa:55"]="超强闪光弹的强烈光芒消除了所有潜行掩护。"}}
D.SpellTexts[89812]={Aura={["8c1dc313bdab0fd2:75"]="这些狼人潜行得无比小心，只有世界上最强大的照明弹才能发现他们。"}}
D.SpellTexts[89819]={Description={["3e3fd974b25f0d8d:85"]=S[19926]}}
D.SpellTexts[89820]={Description={["9bd7854d85affb2a:47"]=S[16858]}}
D.SpellTexts[89821]={Description={["f887ded0f50b833b:43"]="用赫尔库拉的黑暗魔法强化一名黑暗游侠。"},Aura={["64af7770e4bfe689:11"]="强化。"}}
D.SpellTexts[89822]={Description={["6f8f62c29bcc3781:58"]="使用爪钩将漂浮的铁木油罐拽向你。"}}
D.SpellTexts[89824]={Aura={["44034e3675362b85:31"]="获得赫尔库拉黑暗魔法的力量！"}}
D.SpellTexts[89828]={Description={["e3f7d316c72d5b31:42"]="给一台铁木伐木机加油，让它能更好地工作。"}}
D.SpellTexts[89829]={Description={["fc5d0fc9f533b518:49"]=S[20125]},Aura={["fc5d0fc9f533b518:49"]=S[20125]}}
D.SpellTexts[89830]={Description={["30cdadcb470eeece:32"]="让一名地精工人恢复神智。"}}
D.SpellTexts[89835]={Description={["9d80f99b6a587f5c:45"]="使你在巴拉丁典狱官阵营的声望提高250点。"}}
D.SpellTexts[89836]={Description={["4fe65bf96fd1fec8:46"]="你的地狱咆哮近卫军声望提高250。"}}
D.SpellTexts[89839]={Description={["c5f78ecea4813d87:79"]="抓住附近的一名敌人，将其体内的生命力压榨出来，每秒造成一次自然伤害。"},Aura={["1697b1710240ca1c:29"]=S[15446]}}
D.SpellTexts[89842]={Description={["b0702070126a7907:37"]="为附近的盟友提供饮料。"}}
D.SpellTexts[89890]={Description={["231897241317e72b:280"]="当高等精灵与阿曼尼巨魔之间爆发战争的时候，那些精灵无法理解巨魔的魔法武器怎么可能比他们的更加强大。于是，他们从赞扎这样的巨魔法师那里窃取远古知识，并使用这样的神像塑造出高等精灵所特有的巨魔魔法。"}}
D.SpellTexts[89891]={Description={["8204e407be1d072c:193"]="这个小东西来自于一块有毒的红色火山矿石。它背面的铭文表明它本属于巨蛇冥洛斯。一些藤壶留在上面的痕迹说明这块宝石曾在水下渡过了许多岁月。"}}
D.SpellTexts[89892]={Description={["265b2451be259dcc:39"]="向附近的油井投掷炸弹，将其点燃。"}}
D.SpellTexts[89893]={Description={["5c4f470f07fa3dba:144"]="上层精灵的首都，女王艾萨拉巧夺天工的旷世名城，却在漫长的岁月中渐渐腐朽，最终在第一次大分裂中彻底毁灭。这片废墟就是现在的厄运之槌。"}}
D.SpellTexts[89894]={Description={["815faeff338c5886:192"]="这是一支巨大的投掷战刃，精灵们曾经将它放置在攻城武器上，射向敌军。虽然投掷战刃在今天只是很普通的武器，但这支古老的标枪上还镌刻着精致的装饰花纹。即使以暗夜精灵的标准判断，它也是一件精美的工艺品。"}}
D.SpellTexts[89895]={Description={["9deb9e3463fd31e9:161"]="鹦鹉螺是一种已经灭绝的带壳软体动物。外壳可像矛一样长，也可以扭曲成各种形状。这个化石标本体型较小，它们一般可以长得更大。"}}
D.SpellTexts[89896]={Description={["c5d3aad56587572e:173"]="它所呈现的可能是伊瑟拉的配偶——伊兰尼库斯的形象。他曾经堕入翡翠梦魇，后来终于得到了救赎。在这枚指环内部，雕刻着暗夜精灵语：“Andu-falah-dor!”"}}
D.SpellTexts[89899]={Rank={["9be076a0b7821de7:7"]="被动"}}
D.SpellTexts[89904]={Description={["7079553606ad6897:39"]="打击一个敌人，造成物理伤害。"}}
D.SpellTexts[89914]={Description={["9068e87698bd0b29:44"]="使用这件宝物的力量，关闭一座元素之门。"}}
D.SpellTexts[89918]={Description={["a79ac63f6d11908a:69"]="重击地面，造成伤害并使周围地面在短时间内变得不稳定。"}}
D.SpellTexts[89929]={Description={["45106f70a8adbed7:49"]="右键点击以召唤或解散你的翻滚岩灵。"}}
D.SpellTexts[89930]={Description={["7979cba5fe6ca440:50"]="右键点击以召唤或解散你的呼啸风灵。"}}
D.SpellTexts[89931]={Description={["aeecef587cfb35c1:49"]="右键点击以召唤或解散你的涡流水灵。"}}
D.SpellTexts[89932]={Description={["fce1de3aecd9edfb:77"]=S[12587]}}
D.SpellTexts[89933]={Description={["ab927b32423d9bad:31"]="对遭受此能量冲击点敌人造成伤害。"}}
D.SpellTexts[89964]={Description={["82a3c2da57ffb269:50"]=S[17411]}}
D.SpellTexts[89972]={Description={["4c778c5561190286:56"]=S[9413]}}
D.SpellTexts[89975]={Description={["9c26a4b1bb5a1d48:29"]="召唤烽焰以得到任务。"}}
D.SpellTexts[90044]={Aura={["028f7ed69f23d2c9:75"]="免疫法术打断。\r\n一段时间后解除所有束缚效果。"}}
D.SpellTexts[90045]={Aura={["c92f412041843b3f:12"]="不可阻挡。"}}
D.SpellTexts[90046]={Description={["93b5f25333fc91e0:50"]=S[9670]}}
D.SpellTexts[90048]={Description={["e537a409b238cd70:21"]="把他从水里炸出来！"}}
D.SpellTexts[90071]={Aura={["b42a005c166a56bf:7"]="飞行中。"}}
D.SpellTexts[90076]={Description={["6db19e84fc5b47d9:60"]="向一名敌人吐出烈火，对其所在区域造成火焰伤害。"}}
D.SpellTexts[90079]={Description={["df0c42b8b16779a9:35"]="召唤一头黑曜石蔽体龙。"}}
D.SpellTexts[90089]={Description={["17a7738796ebbf36:51"]="检查失落残片或者它的目标是否完成。"}}
D.SpellTexts[90090]={Description={["2684af66eeb0e871:57"]="检查简化生产或者他的目标是否完成。"}}
D.SpellTexts[90096]={Description={["1177f89c220d5e73:42"]="造成火焰伤害，并击倒附近的敌人。"}}
D.SpellTexts[90099]={Description={["90fec1906f20b973:38"]="凝视敌人，使其受到的伤害提高。"}}
D.SpellTexts[90135]={Description={["fed5c5b431d3a8d9:18"]="将敌人击开。"}}
D.SpellTexts[90139]={Description={["d7133a8c7eaceff3:50"]="将你包裹在一个隐形场中，让你隐身。"},Aura={["5cbe8c66683bfb7f:8"]=S[21317]}}
D.SpellTexts[90156]={Description={["fcbb0672568cc8dd:54"]="引导一个刺枝小精灵，将它带回到莱罗斯·疾风那里去。"}}
D.SpellTexts[90208]={Aura={["615de33e519aaddd:17"]=S[19916]}}
D.SpellTexts[90257]={Aura={["9b9c2cb657d7a069:14"]=S[2069]}}
D.SpellTexts[90265]={Description={["706e9dd69d036b09:56"]="你的飞行坐骑现在将获得最快的移动速度。"}}
D.SpellTexts[90266]={Description={["9133d34be5905a1e:63"]="使玩家能够以最快的速度骑乘快速飞行坐骑。"}}
D.SpellTexts[90267]={Description={["8348c629024b0a6c:66"]="使你可以在东部王国、卡利姆多和深岩之洲使用飞行坐骑。"},Rank={["9be076a0b7821de7:7"]="被动"}}
D.SpellTexts[90292]={Description={["448473d2d9287949:80"]="从被杀死的火焰卫士身上释放灵魂。可以在任何类型的火焰卫士身上使用。"}}
D.SpellTexts[90328]={Rank={["1b0f643ac40a884b:12"]="奖励技能"}}
D.SpellTexts[90332]={Description={["e5b6ad3e26cf4bb9:49"]="在暗炉城的黑铁砧上摧毁这件武器。"}}
D.SpellTexts[90333]={Description={["a754a9ceffc1b70d:76"]=S[12588]}}
D.SpellTexts[90334]={Description={["903b11e668a572a3:32"]=S[9170]}}
D.SpellTexts[90339]={Rank={["d507c2749d1fa4b1:14"]=S[16475]}}
D.SpellTexts[90347]={Description={["93562a1420cffc7d:29"]="使你的狐狸进入嬉戏状态。"},Aura={["9ce19bcfb7704974:31"]="“当你是我最好的朋友……”"},Rank={["1b0f643ac40a884b:12"]="奖励技能"}}
D.SpellTexts[90355]={Rank={["931d87bfa7d51f98:13"]=S[17417]}}
D.SpellTexts[90361]={Rank={["931d87bfa7d51f98:13"]=S[17417]}}
D.SpellTexts[90381]={Aura={["979997f4ce4e183b:8"]=S[13681]}}
D.SpellTexts[90391]={Description={["dd65baabd8c51eae:31"]=S[9661]},Aura={["dd65baabd8c51eae:31"]=S[9661]}}
D.SpellTexts[90396]={Description={["f63fd5c87256f2f7:36"]=S[9596]}}
D.SpellTexts[90397]={Description={["a3ca11be8c32b28b:69"]=S[2271]},Aura={["f63fd5c87256f2f7:36"]=S[9596]}}
D.SpellTexts[90406]={Description={["4359c6f8e0683bd1:46"]="对站在熔岩之池中的敌人造成火焰伤害。"}}
D.SpellTexts[90410]={Description={["35aab1428deb259f:78"]="这位圣骑士在和巨龙卡尔卓葛斯战斗时摔倒，压断了这把剑。"}}
D.SpellTexts[90411]={Description={["7aff99788009c6bf:171"]="你现在只能凭空想象，这件物品曾经被安放在怎样的建筑物上，有着怎样的经历。它的……嗯……敲门锤是一位体态丰满的矮人女性，欢快地笑着，露出大大的牙缝，高兴地携带着不少酒。"}}
D.SpellTexts[90412]={Description={["18204e4f373dd708:244"]="对这只靴跟的细节研究表明，这只原始的足部护具很可能是一件魔法物品。它上面的装饰纹样大部分都很抽象，但你还是能在繁复的漩涡纹样和花结中分辨出一些小型林地动物——松鼠、鹿、也许还有一只臭鼬。"}}
D.SpellTexts[90413]={Description={["96f99f03054fa6ee:107"]="这件物品充分显示了何谓富丽华美和工艺精湛。遍布于其上的花纹生动地表现了跃动的鱼儿和奔腾的激流。"}}
D.SpellTexts[90415]={Description={["a014423f9e0daa66:107"]="从这顶头盔的尺寸来看，黑铁领主锤核可能有着非常巨大的身形，当然也有可能是非常肥胖的身形而已。"}}
D.SpellTexts[90417]={Description={["ec8f1afcf8a7681f:37"]="向黑石深渊中的粮食物资投毒。"}}
D.SpellTexts[90419]={Description={["4d822f81e38b323c:134"]="根据传说，黑铁矮人的铁星王将一棵高等精灵的神圣大树雕刻成这面盾牌，并向它施加魔法，让它变得如同顽石般坚不可摧。"}}
D.SpellTexts[90420]={Description={["77214ed355db90c0:159"]="森林巨魔对植物有着强烈的喜爱。他们的身躯上甚至能生长一些低级植物，比如苔藓和藻类。这也让他们拥有了那种特别的翠绿肤色。"}}
D.SpellTexts[90815]={Description={["16b4adfda58b3d0a:22"]="召唤大地之环。"}}
D.SpellTexts[90421]={Description={["d35b6e1c9c7d14dd:275"]="组成这只手镯的是许多巨魔钱币和抛光的小块碧玉，并用银索连缀在一起。巨魔通常都习惯于用黄金制作首饰，所以这只手镯上的白银可能来自于其他种族的战利品。按照这种推测，它的年代应该不算非常久远。不过手镯上的钱币很不寻常，上面雕刻了一些姿容各异，目带秋波的巨魔女士。"}}
D.SpellTexts[90423]={Description={["656a1ad3980b9fa8:262"]="沙巨魔从祖尔法拉克的圣池中召唤来这条巨大的白色多头蛇，并将它像神祗一样崇拜。加兹瑞拉的鳞片上总是有电流游走。而这个小雕像仿佛也充满了同样的能量。在祖尔法拉克内部，到处都是以这条传奇多头蛇为原型的装饰纹样和建筑构造。"}}
D.SpellTexts[90425]={Description={["f2e81519c278f438:43"]="对轰击区域的所有敌人造成火焰伤害。"}}
D.SpellTexts[90426]={Description={["b0864e1f0e29cb3e:40"]="将一颗火球射进杀戮熔炉竞技场。"}}
D.SpellTexts[90429]={Description={["3a8a2ca44d7c572b:272"]="阿塔莱在赞达拉语中是“忠诚者”的意思。这个扭曲的巨魔部落所信奉的是血神哈卡——一个极端残暴的强大生物。他在古拉巴什帝国的远古之都祖尔格拉布尝到了失败的滋味。这根节杖上装饰着一个蝙蝠图案，它可能与最初的蝙蝠神希里克有关。"}}
D.SpellTexts[90432]={Description={["57313ca64e2f62a9:322"]="魔暴龙是艾泽拉斯史上最庞大陆行掠食猛兽。虽然它们在数百万年以前就已经濒临灭绝，但在今日的一些荒僻丛莽中，仍然有它们的后代繁衍生息。关于魔暴龙前肢的大幅度退化，很多人都提出了相应的理论。这些理论从有助于魔暴龙站立到抚弄雌性魔暴龙，简直无奇不有。显然还需要更多观察。"}}
D.SpellTexts[90433]={Description={["fc8276fb8a6e6df8:146"]="琥珀是树脂的化石。大树流出树脂，是为了淹没伤害自己的昆虫。所以在一些非常罕见的琥珀里，还能看到被包裹于其中的昆虫。"}}
D.SpellTexts[90434]={Description={["ddca683cefb2cb21:63"]=S[20281]},Aura={["ddca683cefb2cb21:63"]=S[20281]}}
D.SpellTexts[90437]={Description={["ddca683cefb2cb21:63"]=S[20281]}}
D.SpellTexts[90441]={Description={["c59844bdfcf7513e:29"]="制造一件使用铭文的物品。"}}
D.SpellTexts[90447]={Description={["fd38f87cf41937ad:42"]="在卡尔德的尸体下面产生一团毒云。"}}
D.SpellTexts[90451]={Description={["7670730993f2ebdc:170"]="这只缀着两把握环的细长瓶子曾经是用来酿造或储存达纳苏斯美酒的。虽然经过了漫长的岁月，你还是能嗅到瓶底干涸的残渣散发出一丝丝淡淡的姜味。"}}
D.SpellTexts[90452]={Description={["61826771d81365f0:212"]="鲨鱼并没有真正的骨骼。它们体内只有软骨。因为鲨鱼习惯以巨大的力量啮咬猎物，所以掉落牙齿对它们而言是很平常的事。为了弥补这一缺陷，鲨鱼都生有多排利齿以不断进行替换，这一过程在它们的一生中从不会停止。"}}
D.SpellTexts[90453]={Description={["7a5cc3a973452de0:96"]="在这块珍贵的宝石底面，你能看到一段精细的镌刻文字：“祝瑟莱斯特的24岁生日快乐。”"}}
D.SpellTexts[90458]={Description={["91869bbd1af221ac:206"]="这只盒子由檀香木雕成，里面安放着一个小巧的机械暗夜精灵和一只夜刃豹。虽然盒子的发条装置已经不再工作，你还是能想象这两个精致的小玩偶在乐曲的伴奏下灵动起舞的样子。八音盒底部刻着一段文字：“我最亲爱的瑟莱斯特。”"}}
D.SpellTexts[90464]={Description={["4e56e011adc90092:338"]="在第一次大分裂之前，暗夜精灵们早已熟知上层精灵的傲慢、贪婪和怪异装扮。据说，唯一能让上层精灵们欣赏的只有他们自己的形象。这些镜子的功用就是让精灵贵妇们能够同时从三个维度观赏她们色彩绚烂的华服美饰。而且，从这些镜子里映照出的倒影往往比那些本已夸张至极的衣着更加斑斓耀眼。"}}
D.SpellTexts[90490]={Description={["6039a8a9eaf141ea:46"]="用水冲击一个敌人，造成自然伤害。"}}
D.SpellTexts[90493]={Description={["a31dcaebf904487c:226"]="对于暗夜精灵来说，族群中出现男性牧师和女性德鲁伊是一个巨大的社会变革。在之前的千万年中，只有暗夜精灵男性才能成为德鲁伊，牧师则是女性垄断的领域。这一对雕像正是为了纪念那个重大而动荡的变革时代。"}}
D.SpellTexts[90504]={Description={["67093f987b359921:147"]="霍鲁兹和他的战友在与巨龙卡尔卓葛斯作战的时候，犯了一个严重的错误。这位传奇勇士也因此失去了性命——他站在了那头巨龙的正后方。这样的事情是绝对不能做的。"}}
D.SpellTexts[90506]={Description={["c85273308074323d:89"]="这根木杖已经在奥术气息的灼烧中变得通体焦黑。它的主人也遭遇了同样的命运。"}}
D.SpellTexts[90509]={Description={["db7c063630a2f827:261"]="这些神器的残片混在了矮人的古器堆里，这把节杖却并非出自矮人之手。而是由野猪人所制造。实际上，它曾经是卡尔加·刺肋使用的武器，也许是矮人英雄们在远征剃刀沼泽时夺取了这件战利品。"}}
D.SpellTexts[90518]={Description={["a322727e49784c0b:173"]="怒炉部族在黑铁矮人的历史中有着漫长的血脉传承。这是怒炉王曾经戴过的项链。他的直系后代，也就是怒炉将军至今还在指挥着黑石深渊的黑铁大军。"}}
D.SpellTexts[90519]={Description={["18801559de91d628:245"]="暗炉家族是黑铁历史上一段长长的污渍。铁领主暗炉是个十足的冷血怪物。他曾经无端折磨并杀害了许多族人。一般认为他是一名术士。但也有不少传闻说他是历史上第一位矮人萨满。"}}
D.SpellTexts[90521]={Description={["6379267e10951953:188"]="机械侏儒是泰坦的造物。就像土灵一样，它们最初应该是泰坦的仆人和管家。这个机械侏儒显然是损坏了，因为它不再专注于自己本来的工作，却只喜欢跟着你跑。"}}
D.SpellTexts[90523]={Description={["6719c81c505fcb3f:47"]="右键点击以召唤或解散你的发条侏儒。"}}
D.SpellTexts[90546]={Description={["8b71a5c8fc977643:57"]="受到一头强大巨怪的保护。只要巨怪还在，赫利克斯就不会死。"},Aura={["c6631bb07ce9053b:50"]="只要巨怪还保护着赫利克斯，他就不会死。"}}
D.SpellTexts[90551]={Description={["765b5f087500c26d:60"]="射出一股魔法能量，对目标敌人造成奥术伤害。"}}
D.SpellTexts[90553]={Description={["3064c4be68640777:361"]="这只圣杯上镶嵌着许多宝石，杯身完全被符文所覆盖，用来举行矮人君王的升天仪式。用这只圣杯喝酒肯定是仪式的一部分。而符文还描述了一场需要由女性矮人战士完成的“剑舞”。这种仪式化而又舞刀弄枪的表演显然是源自矮人历史中曾经有过的崇尚血腥决斗的荒蛮时代。"}}
D.SpellTexts[90558]={Description={["047be2c57ea9d4b6:140"]="这颗牙齿有个巨大的窟窿，也许镶金是为了治疗某种伤病，也许是为了某种可怕的巨魔宗教仪式。"}}
D.SpellTexts[90581]={Description={["371e3e517d699c4e:334"]="达卡莱部落被其他巨魔驱赶到北方，最终在诺森德定居。他们在残酷的环境中生存下来，并建立了自己的国家。巫妖王的到来对达卡莱是一个巨大的威胁。愚蠢的是，他们献祭了自己的动物诸神——毒蛇、雪豹、熊、风蛇、猛犸和犀牛，以为这样就可以击退巫妖王。"}}
D.SpellTexts[90608]={Description={["ecc0577c0b9dceab:359"]="据你的研究，这件珍贵武器，曾是夺灵者哈卡在祖尔格拉布的众多收藏物之一。哈卡在多年前被击败后，这把剑就在许多强大的战士和圣骑士的手上流传着，直到变得支离破碎。重要的是，你现在已经有能力重铸这把剑。不过，一旦诸界的毁灭者再度出鞘，也许会带来麻烦，因为离夺灵者的归来可能也已不远了。"}}
D.SpellTexts[90609]={Description={["6148450ebd9717d7:237"]="这一串珍珠中并没有某一颗是特别硕大的，但令人称奇的是，所有四十二颗珍珠竟然完全一样，没有丝毫差异。它们既非普通珍珠的乳白色，也不是那种罕见的黑珍珠，而是闪耀着一种粉色玫瑰的光彩。在这串珍珠中间，还缀着一枚贝壳。"}}
D.SpellTexts[90610]={Description={["dbe9c08b9c6969fc:261"]="真是令人惊叹，你在这只箱子里找到的精灵玻璃动物足以装满一个动物园。箱子可能原本就是被用来收纳这些动物的。随着时代变迁，这些动物身上难免会出现一些裂纹和瑕疵，但这只牡鹿的头显然是被有意砍掉的。箱子的底部雕刻着一个大写字母——“T”。"}}
D.SpellTexts[90611]={Description={["7fe5f63d20544428:196"]="这只瓶子上系着一张用上等犊牛皮纸写的纸条。“最亲爱的P，得知我们将永远无法在一起，我唯一的愿望就是喝下苦苦的蜘蛛毒液。如果你看到了这封信，那么我希望你也会这样做。愿艾露恩庇护我们的灵魂。”"}}
D.SpellTexts[90612]={Description={["0dea3faddc1a7734:271"]="在上古战争中，暗夜精灵蒙受的许多劫难都是由萨维斯一手造成的。终于，玛法里奥·怒风将他战败，并摧毁了他的身躯。此后，萨维斯的灵魂饱受萨格拉斯的折磨，又被萨格拉斯强行放进一具扭曲的肉体中，成为了第一个萨特。"}}
D.SpellTexts[90614]={Description={["a984f5585f0faa4f:215"]="这些风铃是一系列纹饰华丽、长度不一的青铜管，它们都挂在一根形如藤蔓的青铜细绳上。这件物品显然具有魔法，即使在没风的时候，这些风铃也会演奏出乐曲。"}}
D.SpellTexts[90616]={Description={["e640108a32da08f5:247"]="一般都认为艾萨拉是最美丽的暗夜精灵。不幸的是，从这件长袍过份耀眼的色彩来看，她的审美品位应该像她的许多同胞一样狭窄。“前无古人，后无来者的……艾萨拉。”"}}
D.SpellTexts[90617]={Description={["2d1f9a1f36879d46:258"]="一些探险者协会的成员相信鸟是恐龙的后裔。也就是说，这只迅猛龙可能是鸟的始祖。而这些绒毛很可能揭示了这两个不同物种之间久已失落的联系。或者它可能只是艾泽拉斯诸多奇异生物中的一员。"}}
D.SpellTexts[90618]={Description={["515b36f17ad41144:220"]="这具鱼骨受到厚厚的骨膜保护，双颚上整齐排列着数不清的尖牙。据说海洋曾覆盖了整个大陆，所以在离岸数百里的地方也会发现鱼类化石。"}}
D.SpellTexts[90619]={Description={["65ef531a9e91ce07:90"]="当你用某种可怕的魔法让这副骨架恢复如初的时候。这头怪物立刻活了过来。"}}
D.SpellTexts[90621]={Description={["e3d6bf2fbc5b7610:33"]="召唤或解散一个可供骑乘的黄金狮王。"}}
D.SpellTexts[90622]={Description={["33624b4dadd079aa:161"]="这显然曾是个有生命的蝎子，被镀上了一层黄铜，得以保存下来。底部写着潦草的兽人语：“酋长对你悲剧的刺杀行动感到好笑”。"}}
D.SpellTexts[90625]={Aura={["979997f4ce4e183b:8"]=S[13681]}}
D.SpellTexts[90637]={Description={["a6dd77ac42dce7f9:39"]="右键点击以召唤或解散你的幼狐。"}}
D.SpellTexts[90677]={Aura={["816d1669b04b0b0a:16"]=S[5980]}}
D.SpellTexts[90679]={Description={["167aff6151cd1c0c:73"]="瞄准一只纤小的丘陵小鹿，向它倾注顾问达斯多恩的爱与关怀。"}}
D.SpellTexts[90685]={Description={["575e1a18e9b7a69d:31"]="用恶魔能量强化一只丘陵小鹿。"},Aura={["cc4b3df8eced4737:17"]="愤怒并且不安定！"}}
D.SpellTexts[90694]={Description={["1ef1987f816f85dc:31"]=S[2394]}}
D.SpellTexts[90702]={Description={["a20cf8235f228d94:35"]=S[9300]}}
D.SpellTexts[90720]={Description={["8a4d9ac271082437:72"]="酋长哈尔加在黑牙之战中杀死莫奥格之后，一直保留着这件战利品。"}}
D.SpellTexts[90728]={Description={["df96fb7afe1b97a9:129"]="二十九根蜡烛被用来召唤恐惧魔王亚兹格雷姆。在酋长哈尔加最终将他驱逐之前，他杀死了二十八个兽人。"}}
D.SpellTexts[90730]={Description={["470c6ce447e74025:106"]="酋长哈尔加的老婆娜利姆曾经因为妒火中烧而用它做出了可怕的事情。哈尔加死亡时喷洒的鲜血在它上面留下了斑斑锈迹，直到现在也不曾消褪。"}}
D.SpellTexts[90732]={Description={["a90ec56930a59020:74"]="碎颅者耐克鲁斯的利刃节杖是这位冷血术士惯用的武器。"}}
D.SpellTexts[90734]={Description={["d1a0d2df699e9cd0:208"]="狼和兽人共同生活可能已经有许多个世纪了。当兽人第一次走出黑暗之门的时候，狼群就伴随在他们身边。这个小雕像的细节非常精致，在狼流着涎液的嘴里甚至还叼着一支德莱尼人的手臂。"}}
D.SpellTexts[90736]={Description={["49ffbbf69533668b:42"]="在施法者周围创造一片充盈治疗波的区域。"},Aura={["3413459346b89d70:65"]="每秒回复生命值。\r\n挡开厄索拉斯的伤害性酸液。"}}
D.SpellTexts[90757]={Aura={["45a0c75f333bf1f4:7"]="把我藏起来。"}}
D.SpellTexts[90765]={Description={["251e729e2bd9f727:66"]="根据酸液覆盖你身体的程度造成逐渐增强的自然伤害。"}}
D.SpellTexts[90782]={Description={["bf076719a5a8452c:29"]="被厄索拉斯慢慢消化。"},Aura={["571ea6004e5b6767:65"]="被厄索拉斯慢慢消化。\r\n随着计量表的渐渐提升，伤害也逐渐提高。"}}
D.SpellTexts[90831]={Description={["3d9a2e8b20c67292:151"]="兽人中罕有术士，更罕有像古尔丹这样强大的怪物。这根魔鬼的鞭子由数种不同生物的皮革编成，其中似乎也有人类的皮革。"}}
D.SpellTexts[90832]={Description={["f73556c5d435ccda:213"]="这种瓦片似乎曾经用来大规模装饰德拉诺的要塞或者居室。黄绿色的釉面描上绘着牧群，就像纳格兰今天的样子。周围用纵横的棕黑色边框镶住。"}}
D.SpellTexts[90833]={Description={["f716b3e9e29525d6:101"]="这只酒杯虽然视觉冲击很强烈，但是酒液很容易从眼洞里漏出来。令人产生有一种莫名的欲望……"}}
D.SpellTexts[90843]={Description={["41b95069def87764:203"]="兽人萨满的源头仍然是个谜。在最早的兽人历史中，已经提到了萨满。这个简单的头饰似乎有着久远的过去。它的创造者和第一个拥有者已经被历史遗忘了。"}}
D.SpellTexts[90853]={Description={["45fe3450983e9fa5:135"]="这只纤细的紫色金属环上镶缀着十七枚小铃铛，和一些稍大的黄色吹制玻璃珠。它曾经的主人可能是一位舞者，或者是某个社交名媛。"}}
D.SpellTexts[90860]={Description={["402d0a6c24ebeb79:174"]="这个精巧的小竖琴用一只手就可把玩，像七弦琴一样。它有一个相当大的木制共鸣箱，弦栓上系着七根琴弦，可以用来演奏音乐，不过似乎仅仅适合一些哀伤幽幽的曲子。"}}
D.SpellTexts[90861]={Description={["e701745c6509e0d3:148"]="如果这东西不是被德莱尼用来镇纸的话，那就真不知道是干嘛的了。它像是一滴变成固体的水银，底面是平的，可以稳稳地放在桌子上。"}}
D.SpellTexts[90864]={Description={["0539cfe17c37a52c:201"]="纳斯雷兹姆，又称为恐惧魔王，是燃烧军团的军事和拷问官。他们在沙场上是令人胆寒的战士，但他们更喜欢通过阴谋离间诸国，使其自相残杀。"}}
D.SpellTexts[90871]={Description={["390e7309cabc8b2c:72"]=S[5220]}}
D.SpellTexts[90903]={Aura={["8f08936dc7135c22:28"]="正在受到女妖的凝视！"}}
D.SpellTexts[90954]={Description={["e340f12b373acda6:61"]="使施法者遁入周围环境，无法成为远程攻击的目标。"},Aura={["c6a3a748ce696865:28"]="无法成为远程攻击的目标。"}}
D.SpellTexts[90968]={Description={["e4ac09dee65bde3f:192"]="这支剑鞘的繁复装饰几乎令人眼花缭乱。它的每一寸表面都覆满了雕刻、镀金和铭文。它曾经容纳的武器很可能具有强大的魔法，或者是一件华丽的仪式用品。"}}
D.SpellTexts[90974]={Description={["942a20b817b65d81:171"]="这座烛台能够承载十二支蜡烛。它的表面有许多仿佛正在滴落的蓝色和紫色水晶，其间连接着纤细的链子，布满华丽卷饰。制作烛台的艺术家将自己名字的首字母雕刻在它的底面上——“V. T.”。"}}
D.SpellTexts[90975]={Description={["a8820ca22c8a6ffb:242"]="这是一幅非常正式的肖像油画，表现了一位庄严的德莱尼绅士。虽然这幅艺术品画得相当漂亮，但你有一种感觉，绘制它的艺术家一定是有些不怀好意，因为你能从画面的底部看出来，这位绅士没穿裤子。"}}
D.SpellTexts[90983]={Description={["0c7969dda77f37b2:194"]="这块水晶似乎是某种魔法记录装置。它显示出的信息是一种你无法辨识的语言，但你觉得，它见证或伴随了艾瑞达和纳鲁第一次相遇时的情景。"}}
D.SpellTexts[90984]={Description={["a63a4bab0afc3b6a:336"]="德莱尼在来到艾泽拉斯和德拉诺之前，它们居住在阿古斯，当时他们还都是艾瑞达人。当萨格拉斯觊觎阿古斯时，先知维伦带着他的部分人民逃离了家园。这些人就是现在的德莱尼。剩下的艾瑞达人都成为了燃烧军团的一部分。这个朴素的水晶是维伦逃亡时从阿古斯带走的。底部铭刻着“心系玛凯雷”。"}}
D.SpellTexts[90987]={Description={["755ce66aca36187f:202"]="雷象是生活在德拉诺的一种外形类似于猛犸象的生物。在外域的纳格兰，它们的种群尤其繁盛。德莱尼人驯养雷象作为坐骑。这根一头削尖的长杆正是他们对野性未驯的雷象进行驯化的工具。"}}
D.SpellTexts[90988]={Description={["1412a8118e7f9616:262"]="虽然维库人的技术通常都稍落后于部落和联盟，但这枚钥匙的细节设计实在是令人惊叹。在维库社会中，掌管家庭全部钥匙的都是女人。而她们也总是会把钥匙摆在最显眼的位置以显示自己的身份。“不要打开黑暗祭司萨雷姆的箱子。”"}}
D.SpellTexts[90997]={Description={["c96e2e4e846f7a0d:235"]="维库人锻造的许多斧子形状都相当奇特——它们的斧刃会一直延伸，卷曲到斧头的下方。这可以增大刃部的范围，又能减轻斧身的重量。维库人的武器和工具斧大多是这种样子。有些矮人斧也有类似的外形。"}}
D.SpellTexts[91008]={Description={["8aeba8c1faba210e:185"]="单刃猎刀是许多维库战士的佩刀。它的刀身大而且直，单侧开刃，配有一支简单的握柄。主手抡斧，副手挥舞单刃猎刀，这是维库战士普遍采用的战斗方式。"}}
D.SpellTexts[91012]={Description={["84cf33add8781bb2:143"]="这只用燧石和钢制成的简单打火器是引火用的。它的机身被雕刻成龙头的样子，而扁平的金属刃则仿佛是某种被符号化的鱼。"}}
D.SpellTexts[91014]={Description={["c56396f466aa675f:274"]="这支别针的作用应该是将维库人的大斗篷固定在他们的肩膀上。十字形的别针上有两颗大而钝的牙齿，很像是古代始祖龙的牙。现在已经没有人知道，这支别针的主人保留这两颗牙齿是因为他喜爱这种古老的龙族，还是因为他击败了这个怪物。"}}
D.SpellTexts[91055]={Description={["f2c7f6e5d3af97f0:57"]="为哈里森的炮兵指定攻击地点。"}}
D.SpellTexts[91073]={Description={["71734bfae2110621:74"]="召唤巫医玛艾里的灵魂，使其出现在你面前，然后把魂精变成魔法坠饰。"}}
D.SpellTexts[91726]={Aura={["979997f4ce4e183b:8"]=S[13681]}}
D.SpellTexts[91084]={Description={["c65505e9f86ec468:195"]="看上去戴着这个颈环会有些痛。它的周围围绕着一圈铜色的棘刺，很不幸的是，剑刺都朝内竖着。也许某个符文法师才会戴它，或者说是设计师太过蹩脚。"}}
D.SpellTexts[91085]={Description={["e65e08212db8dd62:69"]="在希尔斯布莱德的预定地点放置一枚地精袖珍核弹。"}}
D.SpellTexts[91089]={Description={["43f88e89208f823c:261"]="始祖龙是当代龙族的原始祖先。根据现在流行的传说，泰坦依照一头巨大的始祖龙——迦拉克隆的样子创造了诸巨龙。现在，迦拉克隆的遗骸仍然能在龙骨荒野找到。始祖龙是一种充满兽性的生物，并不具备真正的龙族那样伟大的智慧和超凡的智力。"}}
D.SpellTexts[91100]={Description={["253c76330be704d2:37"]="周期性地喷吐胃液。"},Aura={["253c76330be704d2:37"]="周期性地喷吐胃液。"}}
D.SpellTexts[91103]={Aura={["0de7253691b76cb3:20"]="用火焰喷射器开火！"}}
D.SpellTexts[91111]={Aura={["88799151a4929ca2:62"]="携带一个火焰喷射器。使用火焰喷射器时无法移动。"}}
D.SpellTexts[91113]={Description={["145f07cf1f1ebdf0:41"]="开启或关闭你的火焰喷射器。"}}
D.SpellTexts[91121]={Description={["7482895b6d747f3e:43"]="这就是你攻击一只爆炸绵羊的结果。"}}
D.SpellTexts[91132]={Description={["e41b63b5d085e2f8:215"]="这些巨型乌贼是猎潮者耐普图隆的仆人。它们通常都栖息在深渊之喉。艾泽拉斯并没有它们的行迹。但这块古老的印痕化石证明了这种强大的生物曾经在千万年前造访过这个世界。"}}
D.SpellTexts[91133]={Description={["5c4f57d46703ec97:284"]="这肯定是蛛魔的作品，不过令人感到奇怪的是，那些居住在黑暗洞窟中的蜘蛛君王们为什么会需要一只日晷。莫非它所借助的光源并非太阳，而是来自于地下矿脉中的某种物质？或者它正代表着阿兹亚基毁灭之后蛛魔与其拉的分道扬镳。"}}
D.SpellTexts[91170]={Description={["9e10734e75855623:246"]="蛛魔女王妮萨阿兹雷被阿尔萨斯·米奈希尔和背叛之王阿努巴拉克杀死在艾卓-尼鲁布的上层王国。作为蛛魔女王，妮萨阿兹雷对她的臣民而言，既是领袖，也是母亲。有传闻说，蛛魔女王们所掌握的知识可以通过基因由母亲传给女儿。"}}
D.SpellTexts[91188]={Description={["6cc4ceadac231156:160"]="这是一件美丽却又令人胆寒的物品。在这颗棱角锐利的巨大红宝石中，你能看见许多极微小的生物，可能是蜘蛛、螨虫或别的什么。它们都在拼命地想要从这座红色牢狱中挣脱出去。"}}
D.SpellTexts[91191]={Description={["3d9b0b756ef184e0:147"]="这只纹饰华丽的匣子表面覆盖着金丝蛛网和纤细凌乱的蛛魔文字。匣子里放着一颗心脏。虽然因为年代久远而变成了灰色。但它看上去肯定还是活着的。现在它缓慢地搏动着，仿佛正处于休眠状态。"}}
D.SpellTexts[91195]={Description={["75fc136af54e922d:48"]=S[6533]},Aura={["75fc136af54e922d:48"]=S[6533]}}
D.SpellTexts[91196]={Description={["b715f42186b6f7a2:16"]=S[20528]},Aura={["b715f42186b6f7a2:16"]=S[20528]}}
D.SpellTexts[91197]={Description={["4e6278867d5adbb1:186"]="这块石雕很可能来自于黑暗的艾卓-尼鲁布。看上去，它像是墙壁或塔楼上的一件装饰品。它的样子介于昆虫和蜘蛛之间，而且曾经被涂满绿色、紫色和金色的漆彩。至今这些残留的色彩还会在光线昏暗的环境里发出荧光。"}}
D.SpellTexts[91209]={Description={["726571f37e6c73b0:214"]="这只玻璃瓶里盛着冰虫那极为寒冷的酸性血液。冰虫是生活在诺森德的一种强大生物。根据传说，蛛魔们正是驾驭冰虫在诺森德的冻土中挖掘出无数的隧道和洞窟，从而建造出艾卓-尼鲁布宏伟的地下城市。"}}
D.SpellTexts[91211]={Description={["5ac615c12ff892c8:246"]="这个奇怪的物品可能是一部庞大卷轴的部分遗物。它是一种纸草和皮革的混合制品，表面覆着大红色深红色的结构图和蛛魔笔迹。“Unhhh-tikk-a-shisss. Kka shir. Na-l bkah a-shisss. Kreesh kik ik ta. Sohk-a tik hiss a-k-k-k。”"}}
D.SpellTexts[91214]={Description={["ca9bcb4c35f52a3f:150"]="普恩古 唉 嘎嗚爾夫瓦塔 瑞烏 哇嘎 嗚爾嘎 嚇嘎 嚇咿嗯 古啦爾。普恩古 唉 嘎嗚爾夫瓦塔 瑞烏 哇嘎 嗚爾嘎 嚇嘎 嚇咿嗯 古啦爾。普恩古 唉 嘎嗚爾夫瓦塔 瑞烏 哇嘎 嗚爾嘎 嚇嘎 嚇咿嗯 古啦爾。"}}
D.SpellTexts[91215]={Description={["4aae9a2b3b8a7a16:291"]="这只小匣子有许多活动嵌板、铰链和暗锁。不管你怎样摆弄它，都无法将它打开，显露出藏在其中的物品。实际上，你都不敢试一下，因为这件黑暗宝物一直不停地对你耳语着：“这是你的错，是你的错，你的错，你的错……”"}}
D.SpellTexts[91219]={Description={["dbc190c17d642820:57"]="巨龙卡尔卓葛斯临死时从心脏里喷出的血液腐蚀了表面。"}}
D.SpellTexts[91220]={Aura={["660b8706d9fe846f:15"]=S[6322]}}
D.SpellTexts[91221]={Description={["e108c88059a6c979:187"]="铁矮人领主燃眼极其喜爱战斗。他以挥舞着两把巨大的战锤而为人熟知。你已经重新拼接出了其中的一把，它已经很久没有得到魔法的滋润了。这意味着另一把还在某个地方，也许它依旧是一件强大的武器。"}}
D.SpellTexts[91223]={Description={["02f6ceff0f9c5210:209"]="铁怒是最强大的黑石深渊君王之一。他的烈焰铁砧纹章至今仍然被印刻在黑石士兵的制服和盾牌上。虽然他已经不再是黑铁大军的统帅，但许多战士仍然在以他的名义驰骋沙场。"}}
D.SpellTexts[91224]={Description={["e0547eb45b9d789d:333"]="佐伊女皇之令和佐伊女皇之誓曾经是一对强大的魔法戒指。你找到的是令之戒。非常可惜的是，当它碎裂的时候，就已经失去了一切魔法力量。另外一枚是誓之戒。现在没有人知道它失落在何处，不过也许依旧保存完好。佐伊女皇是一位世人所知甚少的黑铁统治者。不少矮人纵容她对龙的喜爱，尝试为她偷取龙卵或者幼龙时都丢了性命。"}}
D.SpellTexts[91225]={Description={["b140bc11cf153890:328"]="“铜须”这个词有两重含义：一个矮人部族的名字，以及统治这个部族的家族。王座厅的君王们在统治期间使用过许多节杖。根据传统，铜须君王可以让他的顾问大臣或盟友在某一天的时间里持有他的节杖。这对节杖来说就是个灾难，它们或被带去酒馆，或从山顶掉下来，甚或用来敲打穴居人和其它怪物。"}}
D.SpellTexts[91226]={Description={["f03192c6869cff1f:308"]="据传，布莱尔·护石曾在洛克莫丹附近经营着一家热闹的旅店。他的女儿吉琳远走他乡，最后却传出了一些让她父亲的名望蒙羞的消息。于是布莱尔与一名侏儒术士达成了一个交易，以此能使女儿离家更近一些。术士就把吉琳变成了一块炉石，让她总是会回到旅店。"}}
D.SpellTexts[91227]={Description={["e11342faf10c25e1:379"]="巫王索瑞森是三锤之战中黑铁矮人的领袖。当他败给铜须部族，甚至于丢失了铁炉堡之后，只得撤退到现在被称为燃烧平原的地方，并建立起一座以他的名字命名的城市。为了击败敌人，疯狂的索瑞森无意中召唤来半神拉格纳罗斯。这场召唤仪式摧毁了他的生命，并形成了现今被称为黑石山的巨大火山。"}}
D.SpellTexts[91261]={Description={["e47b5b0045f64723:22"]="打开一个宝箱。"}}
D.SpellTexts[91277]={Description={["9c363a3fc46e04d6:18"]="这个灵魂在燃烧。"},Aura={["9c363a3fc46e04d6:18"]="这个灵魂在燃烧。"}}
D.SpellTexts[91278]={Description={["82ee77dd1ea61306:31"]="在近战中向目标喷吐火焰。"}}
D.SpellTexts[91279]={Aura={["f9f117e4de94fe87:45"]="偶尔会向近战范围内的生物喷吐火焰。"}}
D.SpellTexts[91281]={Description={["4b705aac1d83c1bb:28"]="护送信使前往库斯海文。"},Aura={["ffa26f1adfda2f77:56"]=S[6796]}}
D.SpellTexts[91290]={Description={["f87a1ce3c208f3e4:65"]="谢绝金钱奖励，可以让你的拉穆卡恒声望提高1000。"}}
D.SpellTexts[91292]={Description={["f7fd8174a45a4ce9:31"]="假装痛饮杯中酒。"}}
D.SpellTexts[91295]={Description={["9ab2b77c22db3293:64"]="对附近的敌人发动剑刃旋风，造成普通伤害。"}}
D.SpellTexts[91303]={Aura={["99ed012aca1ee059:21"]="你变节了！"}}
D.SpellTexts[91304]={Description={["3433b09b035fe32a:75"]="以暗影能量抽击奇美隆，造成极度的痛苦，打断争执。"}}
D.SpellTexts[91315]={Aura={["b056032dab713168:32"]="你感到自己被注视着……"}}
D.SpellTexts[91317]={Aura={["97c10e815f27e342:20"]="膜拜古加尔！"}}
D.SpellTexts[91322]={Aura={["cbdf4f803125c409:24"]="无法触发慧眼。"}}
D.SpellTexts[91343]={Description={["04c4362122e0737a:47"]="右键点击以召唤或解散迷你页岩蛛。"}}
D.SpellTexts[91395]={Aura={["9c94de94fb46aa3d:38"]="打扮成军情七处特工的模样。"}}
D.SpellTexts[91397]={Description={["b715f42186b6f7a2:16"]=S[20528]}}
D.SpellTexts[91398]={Description={["a57635f3bee9d8fa:83"]=S[16264]},Aura={["a57635f3bee9d8fa:83"]=S[16264]}}
D.SpellTexts[91400]={Description={["2848ce8b9aa4ef98:45"]="在附近放置一桶提神的药剂之水。"}}
D.SpellTexts[91410]={Aura={["5cbe8c66683bfb7f:8"]=S[21317]}}
D.SpellTexts[91414]={Aura={["fb4c7b359e317e66:41"]=S[19117]}}
D.SpellTexts[91551]={Aura={["491404346e305ef3:43"]="记住你随时可以驾驶跑车畅游。"}}
D.SpellTexts[91574]={Aura={["d3e61a465e8c22b5:10"]="毁灭。"}}
D.SpellTexts[91604]={Aura={["cccee74a95ce523b:63"]="警告，你已进入空气稀薄的禁飞区。"}}
D.SpellTexts[91605]={Description={["c5a091628c6f53c5:24"]="显示一幅赛道地图。"},Aura={["2312758cdb3819f3:34"]="使你看到距离终点还有多远。"}}
D.SpellTexts[91615]={Aura={["a673bc9347701d7a:42"]="这只动物有些不对劲……"}}
D.SpellTexts[91646]={Description={["14296660de7c6cf1:88"]="制造一株向日葵，它会浓缩来自天空中的太阳能。太阳能可以被用来培育其它植株。"}}
D.SpellTexts[91647]={Description={["137a9cba3d8293a5:73"]="使一个寒水大地图腾能量过载，令其对附近所有人释放能量。"}}
D.SpellTexts[91649]={Description={["f5e37278f346ba0b:49"]=S[3701]}}
D.SpellTexts[91651]={Description={["a67dca10e33fb025:37"]=S[13703]},Aura={["e0e20c82ed97db71:38"]=S[5659]}}
D.SpellTexts[91668]={Aura={["8d73c1fe872451af:35"]="造成物理伤害的强度发生改变。"}}
D.SpellTexts[91680]={Description={["6f5341c85d64d731:55"]="制造一个疫病传播者，它会剪除碰到的敌方单位。"}}
D.SpellTexts[91681]={Aura={["f8d132bbcf9bb354:9"]="准备好！"}}
D.SpellTexts[91683]={Description={["0f196fc4d4f92be5:40"]="制造一个植物学家布雷泽来帮助玩家。"}}
D.SpellTexts[91687]={Description={["d215a35f528eafb4:39"]="用太阳能量强化药剂师林度恩。"}}
D.SpellTexts[91688]={Description={["841ec56e6572df19:27"]="制造浓缩阳光。"}}
D.SpellTexts[91704]={Description={["a4ca663161d5f9dc:54"]="制造一颗岩石坚果，它会吸收食尸鬼的攻击。"}}
D.SpellTexts[91710]={Description={["03aa0feb8bb34dbe:66"]="制造一株绞杀藤，它会绞缠并逐渐杀死1个正在攻击的食尸鬼。"}}
D.SpellTexts[91722]={Aura={["7f779f4ac9e49a23:15"]=S[15495]},Rank={["1044fc4216ed2ac5:5"]=S[17700]}}
D.SpellTexts[91731]={Description={["34cd270c609c481d:67"]="改进过的黑曜石合金使死神原型机对火焰伤害免疫。"},Aura={["cdd821e66a23350b:19"]="对火焰伤害免疫。"}}
D.SpellTexts[91732]={Description={["a9c2a615e7a263b2:29"]="死神原型机离线了。"},Aura={["8ea536cf2704d270:11"]="需要电击！"}}
D.SpellTexts[91733]={Description={["ab9c9bbca11a3a65:117"]="已充能！持续释放火花，激活其它脱线死神。更多的jolt会伤害被激活的机器。"},Aura={["f988c27ed78dc0e5:107"]="持续释放火花，激活其它脱线死神。更多的jolt会伤害被激活的机器。"}}
D.SpellTexts[91739]={Description={["139e61f187528ce8:33"]="制造一个僵尸攻击植物。"}}
D.SpellTexts[91740]={Description={["430a4e48aa31cfdf:60"]=S[3692]}}
D.SpellTexts[91743]={Description={["e314e78c7afbbd1b:27"]="召唤一个知识之泉。"}}
D.SpellTexts[91744]={Description={["e9fd5070121223dd:24"]="召唤一个灵魂之影。"}}
D.SpellTexts[91748]={Description={["df70bfa1beca604e:44"]="对一名敌人喷吐毒液，造成自然伤害。"}}
D.SpellTexts[91749]={Description={["fc53bd5171f389c0:43"]="把风铃放在空中看看天气如何。"}}
D.SpellTexts[91750]={Description={["cbc524776b990ce4:30"]="使你获得100点太阳能量。作弊器"}}
D.SpellTexts[91751]={Description={["9b6eef92b19f161d:17"]="千里眼……"},Aura={["9b6eef92b19f161d:17"]="千里眼……"}}
D.SpellTexts[91752]={Description={["11678972a7d9d56f:40"]="目睹纳鲁来临的记录。"}}
D.SpellTexts[91753]={Description={["f5a75d978b822df8:15"]="最后的圣物。"}}
D.SpellTexts[91754]={Aura={["36da86a19abd4d76:31"]="获得上古之神的祝福。"}}
D.SpellTexts[91756]={Description={["a497b188c0909623:35"]="徒劳地想要打开迷箱。"}}
D.SpellTexts[91757]={Description={["2391812bb9e313a4:327"]="泰兰德·语风是艾露恩的高阶牧师，新近成婚之后，她已不再是暗夜精灵唯一的领袖了。她在距离永恒之井非常遥远的古城苏拉玛中长大，与玛法里奥·怒风和伊利丹·怒风兄弟俩相距不远。她甜蜜的童年和她随后充满哀伤与冲突的人生形成了鲜明的对比。"}}
D.SpellTexts[91760]={Aura={["582b3498fb8eb143:12"]="变形。"}}
D.SpellTexts[91761]={Description={["7683a5976329a98a:283"]="永恒之井爆炸之后，卡多雷文明的中心随之沉入海底。为了逃避灭亡的命运，艾萨拉女王和一种强大的力量达成了契约。那也许是一位上古之神，或是一个元素。而由此产生的诅咒让幸存下来的上层精灵变形成海蛇一样的扭曲生物，也就是现在我们所熟知的纳迦。"}}
D.SpellTexts[91762]={Description={["cea356ec02c95379:283"]="巨魔战争中，奎尔萨拉斯精灵在阿曼尼巨魔的进攻下步步败退，距离彻底溃败只差一线。在绝望中，他们向阿拉索的人类传授了奥术魔法的精义。能够向他们学习的人类只有一百名，这是击败巨魔所需要的最少人数。这些人类在掌握施法技巧时显得相当笨拙，但他们对魔法都有着一种天生的热爱。"}}
D.SpellTexts[91766]={Description={["cac0b2b470bab851:237"]="虽然这只精灵卷轴匣上有许多精美的装饰和雕刻花纹，但真正令人感兴趣的还是封锢在其中的达纳苏斯语信笺。“派拉蒙德，你绝不能继续在那个酒馆侍女身上浪费时间了。你的母亲和我禁止你这样做。她的地位根本就配不上你。”"}}
D.SpellTexts[91769]={Description={["abb1d04e54dfbb27:258"]="这种圆形利刃是暗夜精灵斥候们喜爱的武器。暗月刀的使用者之中，最著名的莫过于玛维·影歌。今天仍然有许多暗夜精灵在使用它，比如海加尔山的深穴看守者。你发现的这把暗月刀很可能曾经是一件魔法武器，只是它现在已经变成了一堆残片。"}}
D.SpellTexts[91771]={Aura={["c95fac3fb672f880:7"]="变为小精灵。"}}
D.SpellTexts[91773]={Description={["f176ee58d98e8f47:322"]="小精灵是自然的灵体。人们普遍认为它们是死亡暗夜精灵的化身。它们的存在与它们的森林家园和暗夜精灵有着紧密而广泛的联系。在精灵社会的维护与守卫中，它们扮演着重要的角色。在第三次战争的最后一刻，无数小精灵为了击败阿克蒙德而摧毁了自己。所以，今天世界上小精灵的数量已经远远少于往日了。"}}
D.SpellTexts[91775]={Description={["bafca7ff97826bb0:217"]="这座小小的方形城堡是用沙粒塑造的。它的方形塔楼和太阳图案表明它是一座托维尔建筑。但你在奥丹姆从没有见过这种结构的城堡。你只能确定它完全由沙子构成，而不是砂岩，只是你不知道是什么力量将这些细沙凝聚在一起。"}}
D.SpellTexts[91779]={Description={["28cfd46c5b3586a1:122"]="这只粘土的小猫雕像栩栩如生地表现了猫的姿态和表情。在雕像的底面刻着，“纪念查莱克斯，尼特加尔皇帝钟爱的宠物。”"}}
D.SpellTexts[91780]={Description={["eed9eefff7f63834:86"]="“献给尼特加尔皇帝暨登基之礼。我们期待您的长治久安。”"}}
D.SpellTexts[91782]={Description={["315542280afba2f9:197"]="这件小艺术品由亮蓝色、绿色和沙黄色的碎陶片拼嵌而成。“我们衷心地希望，虔诚地祈祷，只愿尼特加尔皇帝结束这场饥荒，让拉穆卡恒重现荣光！”"}}
D.SpellTexts[91785]={Description={["872962ff9c95ad40:246"]="这把弯刀与其说是武器，到更像是一件工艺品。它的刀刃只有几寸长，而且上面看不到什么战场拼杀的痕迹。装饰性的刀柄头上雕刻着一圈圈细小的文字。“尼特加尔皇帝率领我们夺取胜利！Kadesh！Osadi！Satekh！”"}}
D.SpellTexts[91786]={Description={["4e0d20729b6782bf:32"]="缠住一名过路人，并将其拖进去。"}}
D.SpellTexts[91787]={Description={["0680b31d37e20496:54"]="把弗林特洛克的炸药放在裂天号的船腹。"}}
D.SpellTexts[91788]={Description={["5908be19c216a928:60"]="向敌人发射一颗炮弹，造成严重伤害，并使目标昏迷。"},Aura={["979997f4ce4e183b:8"]=S[13681]}}
D.SpellTexts[91790]={Description={["5377d93645e437d5:117"]="放有尼特加尔大帝的石化内脏。人民期待着他的盛世之治，然而却早年驾崩。"}}
D.SpellTexts[91792]={Description={["10ad6fc11032bbe6:206"]="这是一些关于建筑设计的草图。而它们所表现的肯定是一座只应在梦境中出现的宏伟宫殿。你唯一可以确认的就是，在当代奥丹姆，没有任何与此类似的建筑。可能这是一座从不曾被实际建造过的宫殿。“奉尼特加尔皇帝之命。”"}}
D.SpellTexts[91793]={Description={["6826d0ee69b4c16d:195"]="铸铁是黑铁部族著名的建筑师。正是他监督建造了巨石水坝和黑石深渊的很大一部分。据说他的灵魂至今还在黑石山中游荡。"}}
D.SpellTexts[91797]={Aura={["979997f4ce4e183b:8"]=S[13681]}}
D.SpellTexts[91800]={Aura={["979997f4ce4e183b:8"]=S[13681]}}
D.SpellTexts[91807]={Aura={["76d64388f2e6553f:12"]=S[13477]}}
D.SpellTexts[91809]={Description={["4862db53765b9024:24"]="跳跃到敌方目标的背后。"}}
D.SpellTexts[91815]={Description={["3360e156da61385f:114"]="熔融的钢铁保护施法者，阻挡部分魔法攻击，并对附近的所有敌人造成火焰伤害。施法者受到的魔法伤害减少50%。"},Aura={["9986fe7ac8ff2dd5:62"]="受到的魔法伤害减少50%。\r\n对附近的敌人造成火焰伤害。"}}
D.SpellTexts[91819]={Description={["dd65baabd8c51eae:31"]=S[9179]}}
D.SpellTexts[91830]={Description={["fe032c59ca3c9c3a:73"]=S[2274]},Aura={["c4c4166a3a7b2fb5:36"]="注视。\r\n一个熔火炉渣向你扑过来了。"}}
D.SpellTexts[91832]={Description={["7afac03fc019b3d6:34"]="积攒黑翼的狂怒。"},Aura={["f8e2dea39f2e0150:8"]="原始狂怒。"}}
D.SpellTexts[91833]={Description={["79b1648ca0e4bca9:61"]="你的近战攻击有一定几率使你获得黑翼的原始狂怒。"}}
D.SpellTexts[91834]={Description={["8576a5e549ae03da:40"]="制造一个食尸鬼，它比僵尸更强悍。"}}
D.SpellTexts[91849]={Description={["c317300b95cf7584:51"]=S[10034]},Aura={["c317300b95cf7584:51"]=S[10034]}}
D.SpellTexts[91951]={Description={["f766e8115beca130:24"]="像蛮锤矮人一样享受聚会。"},Aura={["f766e8115beca130:24"]="像蛮锤矮人一样享受聚会。"}}
D.SpellTexts[91957]={Description={["23812a8a1de09e6f:67"]="在奥丹姆神殿的信号弹指定位置发射一枚信号弹。"}}
D.SpellTexts[91969]={Description={["ba71ddae7969eccd:43"]="用恐怖的暗影能量冲击大地。"},Aura={["3d928d215ce94962:44"]="受暗影巨兽恐怖死亡的影响而昏迷。"}}
D.SpellTexts[91976]={Description={["ec633a1e71855329:55"]="把钟摆的炸药放到指定爆破点。"}}
D.SpellTexts[91978]={Description={["f81af7c815f8179f:58"]="让敌人产生紧张情绪，将他们冻结在原地！"},Aura={["c17d2c2706c53b0e:7"]=S[18936]}}
D.SpellTexts[91979]={Description={["294100c4a6a7606b:80"]="黑暗婚礼的钟声预示着末日的到来。附近的敌人将因为恐惧而麻痹。"},Aura={["6b968cd902a2372c:18"]="因恐惧而麻痹。"}}
D.SpellTexts[91988]={Description={["430a4e48aa31cfdf:60"]=S[3692]}}
D.SpellTexts[91992]={Aura={["45ec8280f3f68803:73"]="你在非战斗状态下的生命值回复速度大大提高。这个法术只在冬泉谷有效。"}}
D.SpellTexts[92001]={Description={["e93c986d24e9e21a:57"]="祈愿者护盾可以防护多种群体控制效果。"},Aura={["311433726f89bdb5:32"]="免疫多种群体控制效果。"}}
D.SpellTexts[92002]={Description={["d4fc2c056ef13f82:30"]="经常忘记他在打谁。"},Aura={["d4fc2c056ef13f82:30"]="经常忘记他在打谁。"}}
D.SpellTexts[92007]={Aura={["4540f20bcf2d22d4:21"]=S[17404]}}
D.SpellTexts[92008]={Aura={["4540f20bcf2d22d4:21"]=S[17404]}}
D.SpellTexts[92011]={Aura={["4540f20bcf2d22d4:21"]=S[17404]}}
D.SpellTexts[92013]={Description={["73d59425a9a6ee66:50"]=S[1108]},Aura={["01fddd6b01cb8ee0:34"]=S[1107]}}
D.SpellTexts[92014]={Description={["eaf72ee5a379e72a:30"]=S[651]},Aura={["eaf72ee5a379e72a:30"]=S[651]}}
D.SpellTexts[92023]={Description={["254017c4828e9eef:55"]="奈法利安握住抓获的目标，使其无法移动。"},Aura={["0f045d80418ee137:12"]=S[13477]}}
D.SpellTexts[92026]={Description={["e1672eadfa7ca054:65"]="等墨水干透之后把它们完全磨成粉而制成。"}}
D.SpellTexts[92038]={Description={["6bbba995d2cdb478:87"]=S[18632]},Aura={["6bbba995d2cdb478:87"]=S[18632]}}
D.SpellTexts[92042]={Description={["87429470280f2cb5:46"]="对附近的敌人造成冰霜伤害，并将其击退。"}}
D.SpellTexts[92048]={Description={["7bc4f3133c730eb0:184"]="闪电导体被奈法里奥斯灌注了暗影，产生暗影灌注效果，使其对周围的盟友产生暗影伤害，伤害值取决于离开暗影灌注的距离。"},Aura={["060e1c69963b330e:22"]="造成暗影灌注。"}}
D.SpellTexts[92051]={Description={["8a72467dad95199e:104"]="对附近所有玩家造成一次暗影伤害。离开暗影导体越远，受到的伤害越高。"},Aura={["8a72467dad95199e:104"]=S[9605]}}
D.SpellTexts[92053]={Aura={["8a72467dad95199e:104"]=S[9605]}}
D.SpellTexts[92067]={Aura={["ef54ecf3bbf54d50:25"]="向附近盟友充电。"}}
D.SpellTexts[92084]={Description={["d61c49aae6a83ce5:31"]="消灭附近的所有植物和僵尸。"}}
D.SpellTexts[92100]={Description={["336f5ac9e41e37fc:54"]="一种强力的化合药剂，使敌人无法移动或作出反应。"},Aura={["979997f4ce4e183b:8"]=S[13681]}}
D.SpellTexts[92113]={Description={["b94f2c64a24beceb:60"]="向一个敌人注入有多种效果的噩梦药剂。"},Aura={["4e0e7aecfcd34181:55"]="在噩梦将你吞噬前回到梵妮莎身边！"}}
D.SpellTexts[92118]={Description={["587b1aadd805fd56:37"]="使地面四处起火。"}}
D.SpellTexts[92119]={Description={["ab927b32423d9bad:31"]="对受到冲击的敌人造成伤害。"}}
D.SpellTexts[92137]={Description={["2a80d305097f82be:276"]="托维尔传说中提到过一个邪恶的神怪。当拉穆卡恒力图消灭他时，为了免于一死，这个神怪将自己的灵魂转入到一只猴子的身体中。转变还没有结束的时候，他就被杀死了。结果他的精华只有一小部分被转走了——仅仅占据了这只猴爪。"}}
D.SpellTexts[92139]={Description={["76cb40f525c055ee:268"]="阿穆纳伊是起源大厅的守卫者之一。如同这座大厅中的其它构造一样，创造阿穆纳伊的目的就是为了保护这个能够重置艾泽拉斯全部生命的强大装置。这里的每一名守卫者都有自己的影响领域。伊希斯特——魔法。阿穆纳伊——生命。塞特斯——混乱。拉夏——太阳。"}}
D.SpellTexts[92145]={Description={["03078e60f8b1689b:238"]="在法老泰博霍泰普统治时期，无数毒蛇如洪潮般席卷维尔纳尔河两岸。人们用尽手段，也无法驱赶这些爬虫。就在这时，第二股洪流出现了。组成这股洪流的是沙漠圣甲虫。这些圣甲虫与毒蛇展开了殊死搏斗，直到双方都死亡殆尽。和平重回大地。"}}
D.SpellTexts[92146]={Description={["472d7f142d8edbdd:31"]="召唤出平和的圣甲虫组成的风暴。"},Aura={["5a8087893c028ae4:18"]="圣甲虫跟随。"}}
D.SpellTexts[92148]={Description={["0d0f1a26a26e6833:294"]="埃基尔是一个崇尚扩张与暴力的虫类种族，它们的邪恶是常人无法想象的。在数千年的时间里，埃基尔和巨魔诸帝国之间不断爆发战争。最终，强大的阿兹亚基文明分裂成北部的艾卓-尼鲁布和南部的安其拉。暗夜精灵在随后的漫长岁月中对其拉进行了成功的压制，直到它们被上古之神克苏恩再次唤醒。"}}
D.SpellTexts[92153]={Description={["ab927b32423d9bad:31"]="使冲击波对敌人造成伤害。"}}
D.SpellTexts[92155]={Description={["e033d31347a79098:56"]="召唤或解散一辆可供乘坐的深蓝其拉作战坦克。"}}
D.SpellTexts[92157]={Description={["a42b8e092ffa64f0:61"]="制造一颗南瓜炸弹，它爆炸时会摧毁附近所有僵尸。"}}
D.SpellTexts[92159]={Description={["d61c49aae6a83ce5:31"]="消灭附近的所有植物和僵尸。"}}
D.SpellTexts[92163]={Description={["e487f5570af9d758:230"]="这件武器属于一系列弯刀中的一把。它们由拉穆卡恒著名的青铜铸造师——伊尔马特打造。每一把刀都代表着四风之灵的一位神怪君主。这四把刀早已失落在历史的长河中，不过假如你能重铸这把，也许另外三把也能够重见天日了。"}}
D.SpellTexts[92168]={Description={["2636cbfb7be298ca:185"]="尼特加尔皇帝留传至后世的故事非常稀少。我们只知道，他在托维尔举行的加冕礼极其盛大辉煌。祭司们预言他将为帝国带来长久而繁荣的统治。但这位皇帝在非常年轻的时候就去世了，他的伟大命运未及展开就已落幕。"}}
D.SpellTexts[92171]={Description={["b715f42186b6f7a2:16"]=S[20528]}}
D.SpellTexts[92177]={Description={["188b0fb246d24415:23"]="单位正在自我销毁。"},Aura={["188b0fb246d24415:23"]="单位正在自我销毁。"}}
D.SpellTexts[92228]={Description={["a4b722ca3ae7608d:54"]="制造一个畸形体，它的强悍和凶暴是不可想象的。"}}
D.SpellTexts[92231]={Description={["47276e585db02e0f:42"]="召唤或解散一头可供骑乘的鬼灵战马。"}}
D.SpellTexts[92232]={Description={["57c312bb37041eb8:41"]="召唤或解散一头可供骑乘的鬼灵座狼。"}}
D.SpellTexts[92249]={Description={["d583641d6664eed2:117"]=S[1176]},Aura={["d583641d6664eed2:117"]=S[1176]}}
D.SpellTexts[92263]={Aura={["b8a842f4ef6e5ba5:30"]="芬克的多功能潜水头盔！"}}
D.SpellTexts[92276]={Description={["7b211303a9ce1b54:23"]="你应该放置一棵喷酸草！"},Aura={["2e727c9eea026d41:32"]="我想，你应该放置一棵喷酸草！"},Rank={["1044fc4216ed2ac5:5"]="等级1"}}
D.SpellTexts[92278]={Description={["156c0f2424973267:37"]="一团机械火花造成自然伤害。"}}
D.SpellTexts[92307]={Description={["b05c16cf5ad96d8c:37"]="标记目标，让冰霜宝珠追踪他。"},Aura={["35c833eb5c136c84:38"]="冰霜宝珠自动指向了你……"}}
D.SpellTexts[92335]={Aura={["eddda3c7f7bbd8ac:29"]="因应急小马泳圈而获救。"}}
D.SpellTexts[92336]={Description={["78627003ae4e3c10:32"]="在你身旁召唤一名死灵仆从。"}}
D.SpellTexts[92337]={Description={["2f0cec3f22a1bc8c:30"]="在你身旁召唤一名死灵步兵。"}}
D.SpellTexts[92339]={Description={["209ff6d7b76c8386:43"]="给予药剂师林度恩绞杀藤种籽。"}}
D.SpellTexts[92340]={Description={["6976814b507aa07c:31"]="撒下一袋绞杀藤的种籽。"}}
D.SpellTexts[92367]={Description={["984eb53cd7a21e4f:93"]=S[21256]},Aura={["984eb53cd7a21e4f:93"]=S[21256]}}
D.SpellTexts[92374]={Description={["0affbea97af4d654:91"]=S[21253]},Aura={["0affbea97af4d654:91"]=S[21253]}}
D.SpellTexts[92380]={Rank={["931d87bfa7d51f98:13"]=S[17417]}}
D.SpellTexts[92402]={Description={["28e9a5821bda9acd:87"]="一股汇聚生命能量的爆破，对死亡位面的敌人具备毒性。该法术可从生命光束中汲取能量。"}}
D.SpellTexts[92425]={Description={["b715f42186b6f7a2:16"]=S[20528]}}
D.SpellTexts[92434]={Description={["c5a00be214b97dd5:40"]="给予药剂师林度恩冻结草种子。"}}
D.SpellTexts[92435]={Description={["6509e2a41dcd0249:24"]="撒下一袋冻结草的种籽。"}}
D.SpellTexts[92440]={Description={["79076996e46a5dcd:88"]="制造一株冻结草，它能够向逼近的食尸鬼射击寒冰能量，降低其移动和攻击速度。"}}
D.SpellTexts[92490]={Description={["b1eaa06798c3fc9a:91"]="一股汇聚暮光能量的爆破，对所有活体生物都具备毒性。该法术可从死亡光束中汲取能量。"}}
D.SpellTexts[92515]={Description={["13ca5b71180627d4:122"]=S[15019]},Aura={["13ca5b71180627d4:122"]=S[15019]}}
D.SpellTexts[92548]={Description={["de8cd1d313791282:42"]="对身边的所有敌人造成大规模冰霜伤害。"}}
D.SpellTexts[92564]={Description={["e0d764b5225b9d66:9"]="疾病。"}}
D.SpellTexts[92596]={Description={["18ec74349862be57:16"]="重新获得法力值。"}}
