D.SpellTexts[93326]={Description={["1299d869d2212e6c:101"]="使你变成一头沙石幼龙，令你可以非常快的速度飞行并在你的后背上携带一位盟友。这是一种飞行坐骑。"}}
D.SpellTexts[93336]={Description={["4b9038fa2f77d85b:153"]="极度炎热的气体围绕施法者，对所有攻击者造成伤害。需要对大量烈焰采取有效防护才能安全地攻破壁垒。"},Aura={["fb9018c865e7ef17:90"]="对所有攻击者造成大量火焰伤害。\r\n只有非常冰冷的攻击者才能穿越结界。"}}
D.SpellTexts[93337]={Description={["9de3c8dc45eb6b83:115"]="你为拉穆卡恒而战。你在85级《大地的裂变》地下城中战斗时获得的所有声望值，也可以同样提升你在他们中的声望。"},Aura={["b20bc40a85efec21:73"]="在85级《大地的裂变》地下城中战斗时获得的所有声望值，也可以同样提升你在拉穆卡恒中的声望。"}}
D.SpellTexts[93339]={Description={["773fc82d9c490078:121"]="你为大地之环而战。你在85级《大地的裂变》地下城中战斗时获得的所有声望值，也可以同样提升你在他们中的声望。"},Aura={["b007447b7de6e66c:79"]="在85级《大地的裂变》地下城中战斗获得的所有声望值，也可以同样提升你在大地之环的声望。"}}
D.SpellTexts[93341]={Description={["bd86f521df5586b4:126"]="你为海加尔守护者而战。你在85级《大地的裂变》地下城中战斗时获得的所有声望值，也可以同样提升你在他们中的声望。"},Aura={["c262b30f7098cfa2:84"]="在85级《大地的裂变》地下城中战斗获得声望值时，也可以同样提升你在海加尔守护者中的声望。"}}
D.SpellTexts[93347]={Description={["741f73b7c108af56:116"]="你为塞拉赞恩而战。你在85级《大地的裂变》地下城中战斗时获得的所有声望值，也可以同样提升你在他们中的声望。"},Aura={["e50d0fa5d9e74300:74"]="在85级《大地的裂变》地下城中战斗获得的所有声望值，也可以同样提升你在塞拉赞恩的声望。"}}
