D.SpellTexts[93440]={Description={["4b4c82c669590179:65"]="一开始，你以为它们是化石。但实际上，它们是本身质地非常坚硬。"}}
D.SpellTexts[93441]={Description={["6c4f84427f15a4ab:239"]="艾露恩是暗夜精灵的女神。暗夜精灵总是将她和双月中最大的一个——白女士联系在一起。虽然她是和平之神，但她并非和平主义者。她的形象之一就是暗夜精灵战士。此时她的职责就是从死者之中遴选勇士，让他们成为飞跃天空的星辰。"}}
D.SpellTexts[93442]={Description={["0a3d3fdc8571fbc3:121"]="虽然这块木头已经不再有任何生命活力，但它的结构组织仍然完整地保留着。看上去，这很可能是一块棕榈树或苏铁类树木的残片。"}}
D.SpellTexts[93443]={Description={["2c98a6bb36c941a0:199"]="这块化石似乎是物种进化中缺失的一环。它同时具有节肢动物和蠕虫的特点。它的体形像蠕虫一样，但短粗的腿却很像是昆虫和甲壳类动物。它的体表还覆盖着天鹅绒一样的纤细绒毛。"}}
D.SpellTexts[93444]={Description={["32532b5dea59f654:106"]="实际上，这只是一把大匕首，但在血顶部落的文化中，任何能够实际使用的器物都可以被当作精致餐具使用。"}}
D.SpellTexts[93445]={Description={["af241477fdb1d0f4:58"]="传送回哈尔琳身边。一次性。只在冬泉谷有效。"}}
