D.SpellTexts[98374]={Description={["2345aa387f8ab6b1:52"]="当敌人分散时范达尔变形成一头猎豹。"},Aura={["65eaa4576dea03b2:55"]="变形成灼热的猎豹来逐个对付敌人。"}}
D.SpellTexts[98379]={Description={["7c3cbbb5f3cec996:116"]="当10人模式有7个或更多敌人聚在一起时，或者在25人模式中有18个或更多的敌人聚在一起时，范达尔将变成一只毒蝎。"},Aura={["2d298ca069bea9f3:64"]="变成一只熔火毒蝎，对付大量的敌人。"}}
D.SpellTexts[98384]={Description={["19910aabbbb48fec:20"]="目标被裹进了蛛网！"},Aura={["19910aabbbb48fec:20"]="目标被裹进了蛛网！"}}
