D.SpellTexts[98508]={Description={["58efc2d19415476e:36"]=S[449]},Aura={["58efc2d19415476e:36"]=S[449]}}
D.SpellTexts[98511]={Description={["74b3fcf5cf9f0ec2:44"]="测量火羽峰上一个热点的温度。"}}
D.SpellTexts[98517]={Description={["26aedbfc6b27fce3:56"]=S[16233]},Aura={["26aedbfc6b27fce3:56"]=S[16233]}}
D.SpellTexts[98518]={Description={["e36ab4aab9ac35a5:78"]=S[9593]},Aura={["e36ab4aab9ac35a5:78"]=S[9593]}}
D.SpellTexts[98520]={Aura={["599c61bf9f070360:98"]="元素之种的持续时间结束时召唤一个熔火地狱火，并对附近所有敌人造成伤害，伤害量视其与熔火之种的距离而定。"}}
D.SpellTexts[98525]={Description={["fddf49c1fd00493e:56"]=S[22087]},Aura={["fddf49c1fd00493e:56"]=S[22087]}}
D.SpellTexts[98531]={Description={["f9e1562a3bcca621:129"]="使目标暂时成为狼人之咒的受害者。变形后，提高近战、远程和施法速度，但是降低护甲值。"}}
D.SpellTexts[98533]={Description={["500216cd7c717942:249"]="龟是一个古老的物种，千万年来几乎没有什么改变。主要分为三类：海龟、陆地龟以及淡水龟。这个壳可能属于一只陆地龟，其貌不扬，不过它几乎坚不可摧，可以做为绝佳的护盾。"}}
D.SpellTexts[98534]={Description={["1ee0748bac38e6fe:49"]="烟尘从流星砸出的焦黑大坑中升起。"},Aura={["1ee0748bac38e6fe:49"]="烟尘从流星砸出的焦黑大坑中升起。"}}
D.SpellTexts[98552]={Description={["e9487dc16ffc0534:41"]=S[20529]}}
D.SpellTexts[98556]={Description={["701441a4ca0bab4d:365"]="很久以前，最忠诚的巨魔战鼓手会用自己的皮来制做他们珍稀的器具。而巨魔那令人难以置信的自身恢复能力使其能够在如此残酷的折磨中生存下来，整个过程漫长而充满痛苦。据说，如果在擂打这样制成的战鼓时被杀害，那么战鼓手的灵魂就会寄于其中……"}}
D.SpellTexts[98557]={Description={["20d3c74d8f7dbb72:42"]=S[20529]}}
D.SpellTexts[98560]={Description={["d1898880cdc7db6f:278"]="包裹在这块巨大琥珀里的人型生物显得十分渺小，已经无法辨识。无论如何仔细观察，也勾勒不出清晰的轮廓。任何研究这块东西的人都会禁不住地诧异，好似它在千年以前曾被奇怪而可怕的力量所感染。"}}
D.SpellTexts[98565]={Description={["1e7bb15c6f228513:45"]="召唤燃烧宝珠攻击施法者的敌人。"}}
D.SpellTexts[98566]={Description={["ad7da1c3b39b99fe:71"]="用密集的风流包裹住施法者，可以吹熄火焰，阻挡敌人。"},Aura={["8f0cd696f60cac89:63"]="受到强风的包围，此强风可以吹熄火焰，阻挡敌人。"}}
D.SpellTexts[98569]={Description={["e71ddead7191cdbe:341"]="与大众想象的不同，维库人饮水角并不是一般的饮水器具。普通人用碗或者杯子来饮用蜜酒和麦酒，而只有那些德高望重的人才能用这样的精致容器来痛饮美酒。而且，对这些维库人而言，授予这样的容器都要举行非常隆重的仪式，通常都由最具地位的女性主持，并宣读一份正式的宣告，表彰授予对象的头衔和功绩。"}}
D.SpellTexts[98571]={Description={["35df99b44b4cb67d:52"]="右键点击以召唤或解散翼手龙宝宝。"}}
D.SpellTexts[98582]={Description={["6aba4a4c6ca8be4f:193"]="这是一只十分可爱的绿色翼手龙宝宝！更棒的是，按她这样的体型发出的音速尖啸，不会对你的耳膜产生任何伤害。当她试着咬你的脸时，就像小蜥蜴或是小鸟在舔你的脸。太可爱了！"}}
D.SpellTexts[98587]={Description={["e38d308672bc0a13:47"]="右键点击以召唤或解散你的巫毒雕像。"}}
D.SpellTexts[98588]={Description={["833ff57a1d67815d:362"]="制造像这样的巫毒雕像然后为其注入生命的活力，是为了协助巨魔巫医每天的日常琐事，比如清洗腰带或者擦干净屋内地面上的血迹。一般用魔精、巨魔汗水或是部族敌人的血肉来为这些雕像充能，或者吞噬一部分主人的灵魂也能达到这样的目的。非常非常少的一部分灵魂，甚至你都察觉不到。想想你的地面会有多干净吧！"}}
D.SpellTexts[98589]={Description={["8165275acfd97541:58"]="暴怒！使体形变大，伤害提高，但减缓移动速度。"}}
D.SpellTexts[98592]={Description={["f08ecbd2d5139061:51"]="在苍穹之脊收集幼龙或雏龙的精华。"}}
D.SpellTexts[98594]={Description={["6709dceff3352c1e:45"]=S[15030]},Aura={["6709dceff3352c1e:45"]=S[15030]}}
D.SpellTexts[98597]={Description={["8b8b02f2b5c09ae5:42"]=S[15406]},Aura={["8b8b02f2b5c09ae5:42"]=S[15406]}}
D.SpellTexts[98613]={Description={["41d1789d6a034362:46"]="保护希萨莉免受火元素的伤害。"},Aura={["41d1789d6a034362:46"]="保护希萨莉免受火元素的伤害。"}}
D.SpellTexts[98614]={Description={["6f7e809ba987e488:51"]="保护索罗和安伦免受火元素的伤害。"},Aura={["6f7e809ba987e488:51"]="保护索罗和安伦免受火元素的伤害。"}}
