D.SpellTexts[98718]={Description={["105e03c810f3ca53:158"]="召唤或解散一头可供骑乘的驯服的海马。这是一种速度非常快的水下坐骑。\r\n\r\n由于他怪异的本性，因此游泳速度不会受到提高或降低坐骑速度效果的影响。"},Aura={["bbfd65611d840cc0:19"]=S[12512]}}
D.SpellTexts[98727]={Description={["e2de762aa8981263:89"]="召唤或解散一个飞翼守护者。这种坐骑的速度会根据你的骑术等级和所在区域改变。"}}
D.SpellTexts[98736]={Description={["5696effc2800f33d:44"]="右键点击以召唤或解散你的守护者宝宝。"}}
D.SpellTexts[98775]={Aura={["d8d2ee1168228b66:27"]="这具躯体上布满了巨大的爪印。"}}
D.SpellTexts[98818]={Description={["4918276865fada83:38"]="击倒一个敌人，迫使其解散坐骑。"},Aura={["ecfe0f93c950c550:29"]="解散坐骑并感到迷惑。"}}
