D.SpellTexts[103966]={Description={["b024c5aa99287099:113"]="玛诺洛斯将他强大的长柄武器淬上恶魔之焰，用它对对手发动近战攻击时有一定几率造成额外的火焰伤害。"},Aura={["0837962effb5771b:38"]="击中后有一定几率造成额外的火焰伤害。"}}
