D.SpellTexts[106182]={Description={["fb86e303ccbc5950:110"]="受到大地守护者萨尔的祝福，获得艾泽拉斯远古巨石坚不可摧的力量。坦克技能的冷却已改变。"},Aura={["e7d9499c859406b3:28"]="坦克技能的冷却已改变。"}}
