D.SpellTexts[106199]={Description={["e569b391e19dc7b2:215"]="死亡之翼的腐蚀在你的血脉中流动。这种腐蚀如果没有很快被移除的话将会发作，使玩家感染上死亡之翼的血液。驱散后该效果将会跳转至一个新的目标，并会变异成血之腐蚀：大地。"},Aura={["0ebcfc42db6eabd9:95"]="死亡之翼的腐蚀在你的血脉中流动。这种腐蚀如果没有很快被移除的话将会发作。"}}
D.SpellTexts[106200]={Description={["0d75ec0275b80955:214"]="奈萨里奥的阴影在你的血脉中流动。这种腐蚀如果没有很快被移除的话将会发作，使玩家感染上奈萨里奥的血液。驱散后该效果将会跳转至一个新的目标，并会变异成血之腐蚀：死亡。"},Aura={["578e4e6876c7a0d9:93"]="奈萨里奥的阴影在你的血脉中流动。这种腐蚀如果没有很快被移除的话将会发作。"}}
